DI=L+[['希腊 diá + légō → dialégomai / diálogos','相互交谈；dia- 是穿过、彼此之间'],['后期拉丁 dialogus → 古法语 dialoge → 中古英语 dialog → dialogue','对话、交谈；后来包括作品中的对白']]
CA=L+[['希腊 katá + légō → katalégō / katálogos','逐项讲出、列出 → 清单、登记册'],['后期拉丁 catalogus → 古法语 catalogue → 中古英语 cathaloge → catalogue / catalog','有条理的目录、名录']]
ID=L+[['法语 idéo- + -logie → idéologie','十八世纪末先指观念的研究'],['英语 ideology','后来常指一套相互关联的观念与信念']]
ANA=L+[['希腊 aná + lógos〔比例、计算〕→ analogía','比例对应、相似关系'],['拉丁 analogia → 英语 analogy','用关系相似的事物说明或推想另一事物']]
W=[
E('logic','英 /ˈlɒdʒɪk/；美 /ˈlɑːdʒɪk/','逻辑；推理方式；道理','把“因为这些条件，所以得出这个结论”之间的连接看清楚。','希腊 lógos 有话语、道理等义，logikḗ 经拉丁、法语进入英语；这里不是把木头 log 加 -ic。',LG,'研究逻辑会问：如果前提成立，结论是否跟着成立？日常 the logic behind a decision 则是问这项决定背后的理由。推理形式正确与前提事实上正确，是两个要分别检查的问题。','follow the logic；the logic behind a decision；formal logic。','logic 关注理由怎样连接；opinion 是一个看法，有看法不表示已给出完整推理。',('I understand the goal, but I cannot follow the logic of this plan.','我理解目标，却看不懂这个计划的推理。'),('The class examined whether the conclusion followed from the premises by logic alone.','课堂分析了结论能否仅凭逻辑从前提推出。'),sources=['https://www.etymonline.com/word/logic','https://en.wiktionary.org/wiki/logic#English']),
E('logical','英 /ˈlɒdʒɪkəl/；美 /ˈlɑːdʒɪkəl/','合乎逻辑的；合理的；逻辑上的','前一步和后一步接得上，让人能看见为什么走到这里。','英语 logic + -al，表示与逻辑有关或符合逻辑。',LG+[['英语 logic + -al → logical','逻辑的；推理有条理的']],'a logical conclusion 是从所给条件合理推出的结论；the logical next step 是顺着已有目标自然应做的一步。技术中的 logical structure 常指概念关系，未必等于物理摆放位置。','a logical explanation；the logical next step；logical structure。','logical 不保证每个前提都正确；先把未经证实的前提放进去，也可能推出形式上整齐的错误判断。',('Testing the smaller model was the logical next step.','测试较小的模型是顺理成章的下一步。'),('Her explanation was clear and logical.','她的解释清楚而有条理。')),
E('logically','英 /ˈlɒdʒɪkli/；美 /ˈlɑːdʒɪkli/','合乎逻辑地；按照推理','让结论沿着理由一步步走来，不靠突然跳过去。','logical + -ly，常把末尾 -cal- 的元音弱化，连读为 /kli/。',LG+[['英语 logic → logical → logically','逻辑 → 合乎逻辑地']],'think logically 描述思考方式；logically follows 表示结论在推理上接得上。它也可用于组织文章，把信息按明确关系排列。','think logically；argue logically；follow logically from…。','chronologically 是按时间先后；logically 是按推理关系，两种顺序未必相同。',('Arrange the evidence logically before writing the conclusion.','写结论前，先按逻辑关系整理证据。'),('That claim does not follow logically from the figures provided.','那个主张不能从给出的数字中合乎逻辑地推出。')),
E('illogical','英 /ɪˈlɒdʒɪkəl/；美 /ɪˈlɑːdʒɪkəl/','不合逻辑的；不合理的','推理走到一半断了线，结论却已经跳到了另一边。','否定前缀 in- 在 l 前同化为 il-，加 logical；不是 ill“生病的”加 logical。',LG+[['英语 il- + logical → illogical','不符合逻辑、理由前后接不上的']],'如果“价格高”就直接推出“适合我”，中间还缺用途、预算等条件。illogical 可以指出这种推理缺口；不喜欢一个结论，本身却不能证明它不合逻辑。','an illogical argument；seem illogical；an illogical conclusion。','unpopular 是不受欢迎；illogical 是推理不成立，不是大家不同意就不合逻辑。',('It would be illogical to blame the new rule for a problem that began last year.','问题去年就开始了，把它怪到新规则上并不合逻辑。'),('The essay moves from one unsupported assumption to another in an illogical way.','这篇文章不合逻辑地从一个未经证实的假设跳到另一个。')),
E('logician','/ləˈdʒɪʃən/','逻辑学家；逻辑学研究者','专门检查推理的规则、结构和边界的人。','古法语 logicien 来自 logique，借入中古英语；现代可对应 logic + -ian，但原有法语职业名称路线。',L+[['希腊 logikḗ → 拉丁 logica → 古法语 logique / logicien','逻辑 → 擅长或研究逻辑的人'],['中古英语 logicien → 英语 logician','逻辑学研究者']],'他可以研究一种推理系统能证明什么，也可以分析论证中的矛盾。logician 不是对任何“讲话很有道理的人”的固定职业称呼。','a mathematical logician；the work of a logician；a trained logician。','logician 研究逻辑；logistician 通常做后勤管理，不能只看拼写相近就混为一类。',('The logician tested whether the two assumptions could both be true.','逻辑学家检验了那两个假设能否同时为真。'),('A logician helped the team express its rules without contradictions.','一位逻辑学研究者帮助团队把规则写得前后不矛盾。'),sources=['https://www.etymonline.com/word/logician','https://en.wiktionary.org/wiki/logician#English']),
E('apology','英 /əˈpɒlədʒi/；美 /əˈpɑːlədʒi/','道歉；歉意；辩护〔较旧或专门用法〕','起初是站出来解释自己，后来更常是承认造成了问题并表示抱歉。','希腊 apología 是辩护的话，经拉丁及法语进入英语；-logy 此处保留话语义，不是“道歉学”。',AP,'make an apology 是作出道歉，accept an apology 是接受道歉。历史书名中的 Apology 可能仍是申辩，不意味着作者认错；看时代与文体才能判断。','offer an apology；an apology for being late；accept an apology。','an excuse 往往解释为什么发生；an apology 现代通常还表达歉意，不能只说理由就算道歉。',('She offered a sincere apology for the delay.','她为耽搁作出了诚恳的道歉。'),('The ancient work is an apology in the sense of a defence, not a confession of guilt.','这部古代作品中的 apology 指申辩，而不是认罪。'),sources=['https://www.etymonline.com/word/apology','https://en.wiktionary.org/wiki/apology#English']),
E('apologize','英 /əˈpɒlədʒaɪz/；美 /əˈpɑːlədʒaɪz/','道歉；表示歉意','把“这件事让你受到了影响，我很抱歉”真正说出来。','英语 apology + -ize；早期也有为某事辩护义，现代最常用的是表示歉意。英式常另写 apologise。',AP+[['英语 apology + -ize → apologize','作出辩解或申辩 → 常指道歉']],'apologize to someone for something，把对象放在 to 后，把事情放在 for 后。不能直接写 apologize someone；也可以为遗憾的情况表示歉意，而不一定承认自己造成了全部问题。','apologize to someone；apologize for doing something；apologize sincerely。','apologize 是行为；apology 是名词，可说 apologize 或 make an apology。',('I apologized to the neighbour for blocking the driveway.','我为挡住车道向邻居道了歉。'),('The host apologized for the technical delay.','主持人为技术故障造成的延误表示歉意。')),
E('apologetic','英 /əˌpɒləˈdʒetɪk/；美 /əˌpɑːləˈdʒetɪk/','带歉意的；抱歉的；辩护性的〔专门用法〕','从声音、表情或措辞里，能看出这个人在表示抱歉。','希腊 apologētikós 经拉丁 apologeticus、法语 apologétique 借入；现代虽能联系 apology，历史上是独立形容词路线。',L+[['希腊 apologeîsthai → apologētikós → 拉丁 apologeticus → 法语 apologétique','适合辩护的、为某事申辩的'],['英语 apologetic','辩护的；后来常表示带歉意的']],'an apologetic smile 是不好意思的笑，be apologetic about a mistake 是对错误表现出歉意。宗教、哲学语境中还可能保留论辩辩护义，要结合上下文。','an apologetic tone；an apologetic smile；apologetic about the delay。','sorry 可以直接陈述感受；apologetic 常描写表现出来的道歉态度。',('He gave an apologetic smile and moved his bag off the seat.','他抱歉地笑了笑，把包从座位上挪开。'),('Her email was apologetic about the misunderstanding.','她在邮件中对那场误会表达了歉意。'),sources=['https://en.wiktionary.org/wiki/apologetic#English','https://www.etymonline.com/word/apologetic']),
E('unapologetic','英 /ˌʌnəpɒləˈdʒetɪk/；美 /ˌʌnəpɑːləˈdʒetɪk/','不表示歉意的；毫不掩饰自己的','知道别人可能不赞成，仍不准备为这件事道歉。','un- “不” + apologetic；否定的是歉意或退让态度。',L+[['希腊 apologētikós → 拉丁／法语形容词 → 英语 apologetic','辩护的 → 带歉意的'],['英语 un- + apologetic → unapologetic','不表现歉意或不愿为自己的立场退让']],'可以批评做错事却不认错，也可以较中性地说 an unapologetic fan“毫不掩饰的爱好者”。同一个词的语气取决于需要道歉的究竟是什么。','remain unapologetic；unapologetic about a decision；an unapologetic enthusiast。','unaware 是没意识到；unapologetic 说态度，不表示当事人不知道别人不满。',('The company remained unapologetic about the sudden change.','对于突然作出的改变，公司仍未表现出歉意。'),('She is an unapologetic fan of old detective films.','她毫不掩饰自己对老侦探电影的喜爱。')),
E('apologist','英 /əˈpɒlədʒɪst/；美 /əˈpɑːlədʒɪst/','辩护者；为某立场辩解的人','面对批评，替某种信念、制度或行为作解释和辩护的人。','借法语 apologiste，经 apologie 接回希腊 apología“辩护”；现代可对应 apology + -ist，但不是“经常道歉的人”。',AP[:-1]+[['后期拉丁 apologia → 法语 apologie / apologiste → 英语 apologist','为某种立场提供辩护的人']],'历史上可中性地指为宗教信仰论辩的人。现代新闻或批评中 an apologist for something 常带指责，暗示他在替不当行为开脱。','an apologist for a policy；a religious apologist；act as an apologist。','advocate 强调支持、主张；apologist 强调应对批评并为之辩护，常更有争议色彩。',('Critics accused him of becoming an apologist for the failed policy.','批评者指责他成了那项失败政策的辩护人。'),('The historian studied the arguments of an early Christian apologist.','历史学家研究了一位早期基督教护教者的论证。'),sources=['https://www.etymonline.com/word/apologist','https://en.wiktionary.org/wiki/apologist#English']),
E('dialogue','英 /ˈdaɪəlɒɡ/；美 /ˈdaɪəlɑːɡ/，亦 /ˈdaɪəlɔːɡ/','对话；对白；沟通协商','话在参与者之间来回走，而不是只沿一个方向输出。','希腊 diálogos 来自 dia- “穿过、彼此之间”及说话成分，经拉丁、法语进入英语；dia- 不是 di- “二”，所以不限定只有两个人。',DI,'小说里的 dialogue 是人物对白；dialogue between groups 是群体间交换看法。可以是多方对话，也可以说人和系统间的交互，人数不是词根规定的。','open a dialogue；dialogue between communities；natural dialogue。','monologue 是一个人的连续讲话；dialogue 强调彼此回应，不只是轮流念各自声明。',('The novel’s dialogue makes the characters feel alive.','这部小说的对白让人物显得鲜活。'),('The workshop opened a dialogue among residents, planners, and shop owners.','工作坊让居民、规划人员和店主展开了对话。'),sources=['https://en.wiktionary.org/wiki/dialogue#English','https://www.merriam-webster.com/dictionary/dialog']),
E('dialog','英 /ˈdaɪəlɒɡ/；美 /ˈdaɪəlɑːɡ/，亦 /ˈdaɪəlɔːɡ/','对话；对白；对话框〔常见技术用法〕','与 dialogue 是同一个词的拼写变体，软件里常用来命名等待你回应的小窗口。','dialog 与 dialogue 共用希腊—拉丁—法语来源；较短拼写保留了早期英语形式，不能把省去 -ue 当成新的词根。',DI+[['英语拼写 dialog','与 dialogue 并行的变体；软件界面中尤其常见']],'a dialog box 可能要求输入文件名、确认操作或选择设置。它不是总让用户“聊天”，但保留了系统提问、用户回应的交互画面。一般文学对白仍多写 dialogue。','a dialog box；open the dialog；close the settings dialog。','dialog 与 dialogue 通常是拼写和领域习惯差别，不是一律分成不同意义的两个词。',('A dialog box asks you to choose a file name.','一个对话框会请你选择文件名。'),('Close the dialog without saving the changes.','关闭对话框，不保存修改。'),sources=['https://www.merriam-webster.com/dictionary/dialog']),
E('monologue','英 /ˈmɒnəlɒɡ/；美 /ˈmɑːnəlɑːɡ/，亦 /ˈmɑːnəlɔːɡ/','独白；长篇独自讲话','舞台上或交谈中，话语一段时间主要由一个人占着。','经法语 monologue，联系后期希腊 monólogos“独自说话”；mono- 是“单一”，-logue 是话语，法语形式也受 dialogue 模式影响。',L+[['后期希腊 mónos + 说话成分 → monólogos → 法语 monologue','独自讲话的；一人的讲话'],['英语 monologue','戏剧独白；也可说日常一个人不停讲话']],'戏剧独白可以对观众，也可以对剧中其他人，不必都是自言自语。日常说 a twenty-minute monologue 往往暗示对方一直说，别人插不上话。','deliver a monologue；an opening monologue；a long monologue about…。','soliloquy 通常特指角色把内心想法独自说出；monologue 范围更广，可以有明确听众。',('The actor opened the play with a quiet monologue.','演员以一段平静的独白拉开了戏剧的序幕。'),('Lunch turned into a long monologue about his new car.','午餐变成了他围绕新车的一大段独角戏。'),sources=['https://www.etymonline.com/word/monologue','https://en.wiktionary.org/wiki/monologue#English']),
E('prologue','英 /ˈprəʊlɒɡ/；美 /ˈproʊlɑːɡ/，亦 /ˈproʊlɔːɡ/','序幕；开场白；序篇','正戏开始前，先铺一小段话或情节，把读者带进去。','希腊 pro- “在前” + 说话成分 → prólogos，经拉丁 prologus、古法语 prologue 进入英语。',L+[['希腊 prólogos → 拉丁 prologus → 古法语 prologue → 英语 prologue','在前面说的话 → 序幕、开篇']],'小说序篇可以发生在主线多年以前，戏剧序幕可以介绍背景；功能是为主体铺路。它不必是作者谈写作过程，那更接近 preface 的常见用途。','a brief prologue；the prologue to a novel；serve as a prologue。','epilogue 放在主体之后收尾；prologue 放在主体之前引入。',('The prologue shows the village before the main story begins.','序篇展示了主线故事开始前的村庄。'),('A short prologue introduced the conflict between the two families.','简短的序幕介绍了两个家族之间的冲突。')),
E('epilogue','英 /ˈepɪlɒɡ/；美 /ˈepɪlɑːɡ/，亦 /ˈepɪlɔːɡ/','尾声；结语；后记式结尾','故事主要冲突讲完后，再补一段，让余波落定。','希腊 epílogos 是收束的话，经拉丁 epilogus、法语 épilogue 等借入；epi- 在这里表示附加、随后。',L+[['希腊 epílogos → 拉丁 epilogus／法语 épilogue → 英语 epilogue','附在末尾的讲话 → 收束故事的尾声']],'小说尾声可能跳到几年后，交代人物的后续生活；也可只是反思整个故事。它仍与作品主体有联系，不是书后任意一页广告。','an epilogue to the story；a short epilogue；the final epilogue。','ending 是任何结尾；epilogue 常是主要叙事结束后另加的一段。',('The epilogue follows the characters ten years later.','尾声写到了这些人物十年后的生活。'),('A brief epilogue explains what became of the abandoned house.','简短的尾声交代了那座废弃房子的后来命运。'),sources=['https://en.wiktionary.org/wiki/epilogue#English','https://www.etymonline.com/word/epilogue']),
E('catalogue','英 /ˈkætəlɒɡ/；美 /ˈkætəlɑːɡ/，亦 /ˈkætəlɔːɡ/','目录；名录；编目；逐项列举','把一堆东西逐个记下来，再排成可查找的清单。','希腊 kata- + légō 形成 katálogos“登记册”，经拉丁与法语进入英语；-logue 在这里与逐项讲述、列举相连。',CA,'图书馆 catalogue 帮你找馆藏，商品 catalogue 帮你查产品。作动词 catalogue a collection 是给藏品编目；a catalogue of errors 则把一连串错误想成一张清单。','a library catalogue；catalogue a collection；a catalogue of mistakes。','list 可以很随意；catalogue 常暗示按一定规则记录，并配有便于识别的细节。',('The library catalogue lists several editions of the novel.','图书馆目录列出了这部小说的几个版本。'),('Volunteers helped catalogue the donated photographs.','志愿者帮助给捐赠的照片编目。')),
E('catalog','英 /ˈkætəlɒɡ/；美 /ˈkætəlɑːɡ/，亦 /ˈkætəlɔːɡ/','目录；名录；编目〔catalogue 的变体〕','同一张有条理的目录，用了较短、在美式英语中常见的拼写。','catalog 与 catalogue 共用希腊 katálogos 的来源；拼写变体不表示另有一个 cat“猫”词根。',CA+[['英语拼写 catalog','catalogue 的常见变体；美式英语与技术语境中广泛使用']],'course catalog 是课程目录，product catalog 是产品目录。作动词时可写 cataloged、cataloging；写作时跟随所用拼写体系，没必要另记一套不同词义。','a course catalog；an online catalog；catalog the items。','catalog 与 catalogue 意思相同；category 是类别，表示分组，而非那张条目清单。',('The online catalog includes photographs of every item.','在线目录包含每件物品的照片。'),('She cataloged the samples before placing them in storage.','她先给样本编了目，再把它们入库。'),sources=['https://www.merriam-webster.com/dictionary/catalog']),
E('anthology','英 /ænˈθɒlədʒi/；美 /ænˈθɑːlədʒi/','选集；文选；独立故事组成的作品集','从很多作品里摘取一些好段落，像摘花后束成一束。','希腊 ánthos“花” + légō“采集”形成 anthología，经拉丁等借入；这里 -logy 接“收集”支线，不是“花卉研究”。',L+[['希腊 ánthos + légō → anthología','采集花朵 → 选收诗歌，如把佳作束成花束'],['拉丁 anthologia／希腊词 → 英语 anthology','诗歌选集 → 各类作品选集']],'an anthology of poems 通常收不同作品，常涉及多位作者。an anthology series 每集或每季可以讲相对独立的故事，不要求人物一直相同。','an anthology of poetry；edit an anthology；an anthology series。','trilogy 是相联系的三部作品；anthology 重在选收，数量不固定。',('The anthology brings together poems by writers from several generations.','这部选集收录了几代作家的诗。'),('Each episode of the anthology series tells a different story.','这部单元剧的每一集讲述一个不同的故事。'),sources=['https://www.etymonline.com/word/anthology','https://en.wiktionary.org/wiki/anthology#English']),
E('trilogy','/ˈtrɪlədʒi/','三部曲','三个各自成篇的作品，又共同构成一个更大的整体。','希腊 tri- “三” + -logía“作品、叙述”形成 trilogía，经拉丁 trilogia 借入英语；不是“三门学科”。',L+[['希腊 trilogía → 拉丁 trilogia → 英语 trilogy','一组三部戏剧 → 相互联系的三部作品']],'可以是三本小说、三部电影或三部相关戏剧。主题或人物联系比仅仅“凑够三个”更关键，三本毫不相干的书通常不叫 trilogy。','a film trilogy；the final part of a trilogy；a trilogy of novels。','trio 是一般的三人或三件组合；trilogy 特别说作品之间的成套关系。',('The second novel in the trilogy follows the daughter’s journey.','三部曲的第二本小说讲述女儿的旅程。'),('The director completed the trilogy after nearly a decade.','导演用了将近十年才完成这套三部曲。')),
E('tetralogy','/teˈtrælədʒi/','四部曲；四联征〔医学用法〕','四个部分合成一组，在作品里是四部，在医学名称里可指四项特征。','借希腊 tetralogía，tetra- “四” + -logía；古希腊戏剧可指三部悲剧加一部萨堤尔剧的一组，后来扩大到一般四部曲。',[['希腊 tetra-〔四〕与 -logía〔话语、作品的组合形式〕','两份来源材料并列'],['希腊 tetralogía → 英语 tetralogy','四部戏剧的一组 → 四部曲；医学借用四项组合义']],'文学中不必四部完全相同风格，只要构成相关整体。医学的 tetralogy 是特定四项组合的命名方式，不表示患有任意四种症状就能套上某个病名。','a tetralogy of novels；the fourth part of a tetralogy；a dramatic tetralogy。','trilogy 数三部，tetralogy 数四部；anthology 不按固定数量命名。',('The author planned the family saga as a tetralogy.','作者计划把这个家族故事写成四部曲。'),('The festival staged the entire dramatic tetralogy over four evenings.','艺术节用四个晚上上演了整套戏剧四部曲。'),sources=['https://www.etymonline.com/word/tetralogy','https://en.wiktionary.org/wiki/tetralogy#English'])
]
W.extend([
E('analogy','/əˈnælədʒi/','类比；相似关系','找一个熟悉的关系，帮你看懂另一个不熟悉的关系。','希腊 analogía 原是比例、对应关系，ana- 加 lógos“比例、计算”，经拉丁及法语借入；不是“分析的学科”。',ANA,'把电流比作水流，是用熟悉的流动关系解释电路的某一面。类比能启发理解，却不是两个对象完全相同的证明；超过相似之处，就要把类比停下来。','draw an analogy between A and B；explain by analogy；a useful analogy。','comparison 可比较任何异同；analogy 常把一组关系借到另一组事物上，用来解释或推想。',('She used the analogy of a crowded road to explain network congestion.','她用拥挤道路作类比，解释网络拥塞。'),('The analogy works for the basic process but fails in the details.','这个类比能解释基本过程，但细节上并不成立。'),sources=['https://www.etymonline.com/word/analogy','https://en.wiktionary.org/wiki/analogy#English']),
E('analogous','/əˈnæləɡəs/','类似的；可作类比的；同功的〔生物学〕','关键作用或关系对得上，可以借一边理解另一边。','希腊 análogos 经拉丁 analogus 形成英语 analogous；现代可联系 analogue + -ous，但不是从英语 analogy 改一个字母得来的历史。',L+[['希腊 aná + lógos → análogos → 拉丁 analogus → 英语 analogous','按比例相应的 → 关系或功能相似的']],'常用 analogous to。生物学中，鸟翼与昆虫翼就飞行功能而言可说 analogous，但并非作为同一祖先的翅膀结构继承而来；讨论的是功能相似，不能由此认定同源。','analogous to something；an analogous situation；analogous structures。','homologous 强调共同来源的对应；analogous 在生物学中强调功能相似，来源可能不同。',('The problem is analogous to finding the shortest route through a city.','这个问题类似于在城市中寻找最短路线。'),('Bird wings and insect wings are analogous as organs of flight.','鸟翼与昆虫翼作为飞行器官是同功结构。'),sources=['https://en.wiktionary.org/wiki/analogous#English']),
E('ideology','英 /ˌaɪdiˈɒlədʒi/；美 /ˌaɪdiˈɑːlədʒi/；亦以 /ɪdi-/ 起读','意识形态；思想体系','一套相互扣在一起的观念，让人据此理解社会、判断什么值得做。','借法语 idéologie，由 idéo- “观念” + -logie 构成；原指观念研究，后来转向某群体的思想和信念体系。',ID,'不是一个孤立想法，而是若干看法怎样连成整体。政治讨论中常用，但不同经济、社会观念也可构成 ideology。这个词本身并不必然等于“错误宣传”。','political ideology；a dominant ideology；an ideology of…。','idea 是一个观念；ideology 是较成体系的观念和信念，范围更大。',('The historian examined the ideology behind the reform movement.','历史学家研究了改革运动背后的思想体系。'),('Their disagreement concerned ideology as well as practical details.','他们的分歧既涉及思想理念，也涉及实际细节。')),
E('ideological','英 /ˌaɪdiəˈlɒdʒɪkəl/；美 /ˌaɪdiəˈlɑːdʒɪkəl/','意识形态的；思想理念方面的','在争论里标出：这里分歧的是一整套信念，而不只是技术办法。','ideology + -ical；主重音移到 -log-，描述与思想体系有关的特点。',ID+[['英语 ideology + -ical → ideological','与意识形态或思想体系有关的']],'an ideological divide 是理念上的分裂，ideological commitment 是对某思想体系的认同。它可以中性描述，也可以在特定语境批评过分教条，不能每次都自动译成“不理性的”。','ideological differences；an ideological divide；ideological commitment。','practical 常看事情怎么做得成；ideological 常看背后的信念，但两种考虑可以同时存在。',('The coalition brought together groups with major ideological differences.','这个联盟把思想理念差异很大的团体联合了起来。'),('The debate moved from costs to deeper ideological questions.','争论从成本转向了更深层的理念问题。')),
E('ideologue','英 /ˈaɪdiəlɒɡ/；美 /ˈaɪdiəlɑːɡ/，亦以 /ˈɪdi-/ 起读','意识形态拥护者；教条主义者〔常带批评〕','遇到新情况，总先把固定的一套信念搬出来的人。','借法语 idéologue，由表示观念的 idéo- 与 -logue 构成；与 ideology 相连，但有独立法语人物名称路线。',L+[['法语 idéo- + -logue → idéologue → 英语 ideologue','围绕思想体系论说、拥护某思想体系的人']],'现代常带批评，强调僵硬地守着理论，不愿调整。历史语境也可能只是特定思想群体成员的名称，所以不要脱离文体一律骂成“极端分子”。','a rigid ideologue；a political ideologue；dismiss someone as an ideologue。','thinker 是宽泛的思想者；ideologue 常突出对某一思想体系的坚定、甚至教条式依附。',('Critics called him an ideologue who ignored inconvenient evidence.','批评者说他是个无视不利证据的教条主义者。'),('The biography explains why her opponents labelled her an ideologue.','传记解释了她的对手为何给她贴上意识形态论者的标签。'),sources=['https://www.etymonline.com/word/ideologue','https://en.wiktionary.org/wiki/ideologue#English']),
E('logarithm','英 /ˈlɒɡərɪðəm/；美 /ˈlɑːɡərɪðəm/','对数','反过来问：底数要乘方到几次，才能得到眼前这个数？','Napier 用希腊 lógos“比例” + arithmós“数”创制新拉丁 logarithmus，英语再借入；不是 log 与 algorithm 的混合。',L+[['希腊 lógos〔比例〕+ arithmós〔数〕→ 新拉丁 logarithmus','近代数学造词：比例与数的联系'],['英语 logarithm','对数；与指数运算互相对应']],'以 10 为底，1000 的对数是 3，因为 10³ = 1000。正数的同底对数把乘法关系化成加法关系，所以早期能大幅减少计算工作。底数要交代清楚，不能看到 log 就认定所有书都用底 10。','the logarithm of a number；a logarithm to base ten；take logarithms。','algorithm 是解题步骤，有另一条词源；logarithm 是数学运算，拼写相似不等于同根。',('The logarithm of one thousand to base ten is three.','一千以十为底的对数是三。'),('Taking logarithms turns the product of two positive numbers into a sum.','取同底对数，可以把两个正数乘积的关系化成和的关系。'),sources=['https://www.etymonline.com/word/logarithm','https://mathworld.wolfram.com/Logarithm.html','https://en.wiktionary.org/wiki/logarithm#English']),
E('logarithmic','英 /ˌlɒɡəˈrɪðmɪk/；美 /ˌlɑːɡəˈrɪðmɪk/','对数的；按比例分档的〔刻度〕','在对数刻度上，走同样远，表示乘同样的倍数。','logarithm + -ic；词尾里的 /ð/ 保留，重音移到 -rithm-。',L+[['新拉丁 logarithmus → 英语 logarithm','比例数 → 对数'],['英语 logarithm + -ic → logarithmic','与对数运算或对数表示有关']],'横轴等距放 1、10、100、1000，就是以固定倍数递增的对数刻度。它能把跨度很大的数放进一张图，不意味着中间的实际数值差相等。','a logarithmic scale；a logarithmic function；logarithmic growth。','linear scale 的等距通常代表等差；logarithmic scale 的等距代表等比。',('The graph uses a logarithmic scale to display values across six orders of magnitude.','图表用对数刻度展示跨越六个数量级的数值。'),('On this logarithmic axis, the distance from ten to a hundred equals the distance from a hundred to a thousand.','在这条对数轴上，十到一百的距离与一百到一千的距离相同。'),sources=['https://www.etymonline.com/word/logarithmic','https://mathworld.wolfram.com/Logarithm.html']),
E('logistics','/ləˈdʒɪstɪks/','后勤；物流；实施安排','把人、物资、时间和地点安排好，让计划真能运行起来。','军事后勤义借法语 logistique；常见分析接 logis“住处、营地”，并受源于希腊“计算”的同形 logistique 影响。旧算术义另接 logistic，不把两条路线硬并成一根。',[['军事旁支：法语 logis〔住处、军营〕→ logistique → 英语 logistics','军队安置、运输、补给 → 后勤与物流；具体构词有讨论'],['并行影响：希腊 logistikós → 数学用 logistique / logistic','计算与推理；影响后勤词的形式，并有旧算术义']],'会议的 logistics 包括谁住哪里、设备何时到、车辆怎样接驳；货运物流则关心物品运输和储存。谈学科常作单数，谈一组安排时也可搭配复数动词，按句意处理。','manage the logistics；transport logistics；the logistics of an event。','strategy 决定要达成什么和大方向；logistics 确保人和物在需要的时候到位。',('She handled the logistics of moving the exhibition to three cities.','她负责把展览移到三个城市的全部运输与安排。'),('Good logistics kept the food fresh throughout the journey.','良好的物流安排让食物在全程保持新鲜。'),sources=['https://www.etymonline.com/word/logistics','https://en.wiktionary.org/wiki/logistics#English']),
E('logistic','/ləˈdʒɪstɪk/；美亦 /loʊˈdʒɪstɪk/','逻辑斯蒂的〔数学〕；后勤的；逻辑计算的〔旧用法〕','先认语境：是在谈补给安排，还是一条先快后慢、趋向上限的数学曲线？','数学支线经法语或中世纪拉丁接希腊 logistikós“善于计算的”；后勤义则接法语 logis / logistique 旁支。逻辑斯蒂曲线名称在近代数学中形成，其命名不能简单解释为“物流曲线”。',[['希腊 lógos → logistikós → 中世纪拉丁 logisticus／法语 logistique','计算、推理相关的词'],['英语 logistic 的数学用法','近代用于逻辑斯蒂曲线、模型与相关方法'],['并列后勤支线：法语 logis / logistique → logistic','与物流、安置、补给有关，不是上述数学意义自动推出来的']],'logistic growth 常描述受到容量限制、后期趋缓的增长。logistic regression 常用于估计类别概率，并非研究物流才用的回归；谈 logistic support 时才是后勤支持。','logistic growth；logistic regression；logistic support。','logarithmic 是对数的；logistic 是另一种函数或相关模型，两个数学形容词不能互换。',('The population followed a logistic growth curve as resources became limited.','资源逐渐受限时，种群增长呈现出逻辑斯蒂曲线。'),('The team arranged logistic support for the remote field station.','团队为偏远野外站安排了后勤支持。'),sources=['https://www.merriam-webster.com/dictionary/logistic','https://en.wiktionary.org/wiki/logistic#English','https://mathworld.wolfram.com/LogisticFunction.html']),
E('tautology','英 /tɔːˈtɒlədʒi/；美 /tɔːˈtɑːlədʒi/','同义反复；重言式、永真式〔逻辑〕','日常可能是换个说法又说了一遍；逻辑里则是怎样赋真值都成立的形式。','希腊 tautó“同一个” + 说话成分 → tautología，经后期拉丁 tautologia 借入；字面画面是反复说同一件事。',L+[['希腊 tautó + -logía → tautología → 后期拉丁 tautologia → 英语 tautology','重复同一意思 → 修辞与逻辑中的不同术语用法']],'修辞中“a beginner who is new to the activity”可能重复了初学者的含义。经典命题逻辑中 P or not P 是重言式：不管 P 真或假都成立；这里的术语不是单纯批评啰嗦。','avoid tautology；a logical tautology；a truth table for a tautology。','repetition 可以有强调作用；修辞上的 tautology 常批评没有增加内容。逻辑上的重言式则是严格性质。',('The editor removed a tautology that repeated the same point in different words.','编辑删去了一处用不同措辞重复同一意思的同义反复。'),('In classical propositional logic, “P or not P” is a tautology.','在经典命题逻辑中，“P 或者非 P”是重言式。'),sources=['https://www.etymonline.com/word/tautology','https://en.wiktionary.org/wiki/tautology#English']),
E('tautological','英 /ˌtɔːtəˈlɒdʒɪkəl/；美 /ˌtɔːtəˈlɑːdʒɪkəl/','同义反复的；重言式的','看似又给了一个理由，实际上可能只是把原话换了外衣。','tautology + -ical；修辞义和逻辑术语义都由名词延伸。',L+[['希腊 tautología → 拉丁 tautologia → 英语 tautology','同义反复；后来有逻辑专门义'],['英语 tautology + -ical → tautological','具有同义反复或永真形式的']],'“可靠，因为它值得信赖”往往只是换词，没有提供独立证据，所以可叫 tautological explanation。逻辑课里的 tautological formula 则说所有赋值下为真，不是评价句子写得不好。','a tautological explanation；a tautological statement；a tautological formula。','circular 常说论证绕回自己；tautological 常说同一内容被重说，或形式恒真，两者有重叠但非所有情况相同。',('Calling the plan effective because it works is a tautological explanation.','说计划有效是因为它管用，是一种同义反复的解释。'),('The students checked whether the formula was tautological by constructing a truth table.','学生们通过列真值表，检查这个公式是否为重言式。')),
E('neologism','英 /niˈɒlədʒɪzəm/；美 /niˈɑːlədʒɪzəm/','新词；新用法','语言里新长出的一块：可能是新造的词，也可能是旧词新添的意思。','借法语 néologisme，由希腊来源的 neo- “新” + log- “词”及 -ism 构成。',L+[['法语 néo- + log- + -isme → néologisme → 英语 neologism','新创造或新使用的词语']],'一个网络社区可以先创造 neologism，之后它可能广泛传播，也可能很快消失。新不等于错，也不等于一定会被收进词典；词的流通情况还要继续看。','coin a neologism；a recent neologism；the spread of a neologism。','slang 是语体特点；neologism 是新旧时间上的特点，新词也可以非常正式。',('The novel introduced a neologism for its imaginary transport system.','小说为虚构的交通系统创造了一个新词。'),('The researcher tracked how the neologism spread beyond the original forum.','研究者追踪了这个新词怎样传播到最初论坛之外。')),
E('logogram','英 /ˈlɒɡəɡræm/；美 /ˈlɑːɡəɡræm/，亦 /ˈlɔːɡəɡræm/','语词符号；语素文字字符','一个符号联系的是词或词素，而不只是一个字母音。','近代 logo- “词” + -gram “写下的符号”；两部分都用希腊来源的构词材料。',L+[['英语 logo- + -gram → logogram','代表词或词素的书写符号']],'例如 & 常直接代表 and，可作为简单说明。实际文字系统可能把语词符号和表音线索混用，所以“有 logogram”不表示系统完全不表示声音。','a written logogram；identify a logogram；logograms and phonetic signs。','pictogram 强调图形像所表示的东西；logogram 强调符号与语言单位的联系，外形不一定像实物。',('The ampersand is a logogram for the word “and”.','符号 & 是代表 and 一词的语词符号。'),('The script combines logograms with signs that indicate sounds.','这套文字把语词符号与表音符号结合起来。')),
E('logophile','英 /ˈlɒɡəfaɪl/；美 /ˈlɑːɡəfaɪl/，亦 /ˈlɔːɡəfaɪl/','词语爱好者','看到一个有趣的词，会忍不住追着它的声音、意思和来历看下去的人。','英语 logo- “词” + -phile “爱好者”；是近代用希腊材料组成的人物名称。',L+[['英语 logo- + -phile → logophile','喜爱词语的人']],'可以喜欢罕见词，也可以细看一个普通词怎样换义。这是兴趣描述，不要求拥有语言学学位；喜欢词语也不意味着说话必须堆满生僻词。','a devoted logophile；a book for logophiles；a logophile’s notebook。','linguist 通常指研究语言的人或精通语言者；logophile 首先说爱好，不保证专业身份。',('As a logophile, she keeps a notebook of words that surprise her.','作为词语爱好者，她用笔记本记录那些让她惊讶的词。'),('The dictionary’s historical notes delighted the logophile.','词典里的历史说明让这位词语爱好者很着迷。'),sources=['https://www.merriam-webster.com/dictionary/logophile','https://en.wiktionary.org/wiki/logophile#English'])
])
ET=[['希腊 étumon〔真实意思〕与 -logía〔论述〕','两个构词来源并列'],['希腊 etymología','追究词的真实意义'],['拉丁 etymologia → 古法语 ethimologie → 中古英语 ethymologie → etymology','逐渐成为研究词语来源与历史变化的名称']]
PH=L+[['希腊 phílos〔喜爱〕+ lógos → philología → 拉丁 philologia','喜爱学习、文献与论说'],['中古英语 philologie → 英语 philology','以文献为依据研究语言、文学及其历史']]
TH=L+[['希腊 theós〔神〕+ 论说成分 → theología → 拉丁 theologia','关于神与神圣事物的论说'],['古法语 theologie → 中古英语 theologie → theology','神学']]
CH=L+[['希腊 khrónos〔时间〕+ -logía → 新拉丁 chronologia／法语 chronologie','近代学术用语：按时间整理事情'],['英语 chronology','年代次序；按时间排列的记录']]
W.extend([
E('etymology','英 /ˌetɪˈmɒlədʒi/；美 /ˌetəˈmɑːlədʒi/','词源；词源学','给一个词查履历：它从哪种语言来，字形和意思一路怎样变。','希腊 étumon“真实意思” + -logía，经拉丁、法语借入；名字保留古人的追本溯源想法。',ET,'现代词源研究靠旧文献、语音变化和借词证据。最早的意思只是履历的一页，不是今天唯一正确的意思；好记的拆词故事也未必是真实词源。','the etymology of a word；study etymology；an uncertain etymology。','entomology 研究昆虫；etymology 追词的历史，少一个 n 就换了领域。',('The etymology of the word reveals an earlier meaning that has disappeared.','这个词的词源揭示了一个已经消失的早期含义。'),('A memorable story is not enough to establish a word’s etymology.','仅凭一个好记的故事，不能确定一个词的来源。'),sources=['https://www.etymonline.com/word/etymology','https://en.wiktionary.org/wiki/etymology#English']),
E('etymological','英 /ˌetɪməˈlɒdʒɪkəl/；美 /ˌetəməˈlɑːdʒɪkəl/','词源的；与词语历史有关的','把注意力放到这个词以前怎样写、怎样说、怎样用。','英语 etymology + -ical；名词末尾 -y 在派生中变化，重音落到 -log-。',ET+[['英语 etymology + -ical → etymological','关于词源的']],'an etymological connection 是有历史依据的词源联系。两个词今天拼得相似，未必存在这种联系；反过来，经过很久的音变，同源词也可能长得很不像。','etymological research；an etymological dictionary；an etymological connection。','mnemonic 是帮助记忆的办法；etymological 说历史来源，记忆法不能替代证据。',('The note explains the etymological connection between the two words.','这条注释解释了两个词之间的词源联系。'),('She checked the claim in an etymological dictionary.','她在词源词典中核查了这个说法。'),sources=['https://www.etymonline.com/word/etymological']),
E('philology','英 /fɪˈlɒlədʒi/；美 /fɪˈlɑːlədʒi/','语文学；历史文献语言研究','把旧文本拿在手里，通过字句、版本和语言变化读懂它。','希腊 philo- “喜爱” + 与话语、学习有关的 -logia，经拉丁借入；不是简单的“爱说话”。',PH,'早期范围很广，涉及学问与文学；现代常联系古代文献、语言史和文本校勘。比较两份抄本为什么用不同词，就是很具体的语文学工作。','classical philology；comparative philology；the study of philology。','linguistics 的范围包括许多当代语言问题；philology 尤其重视文本及历史，两者有交叉。',('Her research in philology compares three medieval versions of the poem.','她的语文学研究比较了这首诗的三个中世纪版本。'),('Philology helped explain a phrase that modern readers had misunderstood.','语文学研究帮助解释了一个被现代读者误解的短语。'),sources=['https://www.etymonline.com/word/philology','https://en.wiktionary.org/wiki/philology#English']),
E('philological','英 /ˌfɪləˈlɒdʒɪkəl/；美 /ˌfɪləˈlɑːdʒɪkəl/','语文学的；以历史文本和语言为依据的','从原文的字句和版本入手，而不是只凭今天的直觉猜意思。','英语 philology + -ical，表示与语文学有关。',PH+[['英语 philology + -ical → philological','运用语文学材料或方法的']],'philological evidence 可能是旧抄本里的拼写、某时代的语法，或不同版本的差异。它能帮助判断一个句子在当时的意思。','philological evidence；a philological study；philological analysis。','literary analysis 可以重在主题和艺术效果；philological analysis 更突出语言和文本的历史证据。',('The editor used philological evidence to restore the damaged line.','编辑利用语文学证据复原了受损的那一行文字。'),('A philological analysis showed that the phrase was older than the manuscript.','语文学分析表明，这个短语比现存手稿的年代更早。'),sources=['https://www.etymonline.com/word/philological','https://en.wiktionary.org/wiki/philological#English']),
E('philologist','英 /fɪˈlɒlədʒɪst/；美 /fɪˈlɑːlədʒɪst/','语文学家','靠细读历史语言和文献，解决旧文本问题的人。','英语 philology + -ist；表示从事这项研究的人，并非必须先经一个同形法语人名。',PH+[['英语 philology + -ist → philologist','研究历史语言与文献的人']],'他可能发现抄写员漏了一个词，也可能追查某种语法何时出现。这份工作既需要语言知识，也需要理解文本所处的时代。','a classical philologist；a trained philologist；the work of a philologist。','logophile 只是词语爱好者；philologist 通常指从事相应学术研究的人。',('The philologist compared the spelling in several early manuscripts.','语文学家比较了几份早期手稿的拼写。'),('A philologist identified the quotation’s original source.','一位语文学家找到了这段引文的最初出处。'),sources=['https://www.etymonline.com/word/philologist']),
E('terminology','英 /ˌtɜːmɪˈnɒlədʒi/；美 /ˌtɜːrmɪˈnɑːlədʒi/','术语；术语体系；术语研究','进入一个领域，先认清大家用哪些专门词来指哪些东西。','拉丁来源的 terminus“术语”与希腊 -logia 结合；经德语 Terminologie 等近代学术造词用法进入英语，并有新拉丁、法语对应形式。',L+[['拉丁 terminus〔词、术语〕+ 希腊 -logia → 德语 Terminologie 等近代形式','给专业概念整理名称；不是古希腊现成的整词'],['英语 terminology','某领域的一套术语；也指术语研究']],'学习医学 terminology，不是只背一串难词，还要知道相近名称怎样划清概念。这个词常作不可数名词，一门领域的术语体系可以说 the terminology of…。','technical terminology；medical terminology；consistent terminology。','jargon 有时批评术语把外行挡在门外；terminology 本身较中性。',('The guide explains the terminology used in the laboratory reports.','指南解释了实验室报告中使用的术语。'),('Consistent terminology makes the two manuals easier to compare.','术语一致，让两本手册更容易对照。'),sources=['https://www.etymonline.com/word/terminology','https://en.wiktionary.org/wiki/terminology#English']),
E('theology','英 /θiˈɒlədʒi/；美 /θiˈɑːlədʒi/','神学','围绕神、信仰和宗教教义，系统地追问它们意味着什么。','希腊 theo- “神” + -logia，经拉丁、古法语进入英语。',TH,'例如某宗教怎样理解神与人的关系、罪与宽恕，就可以成为神学问题。神学常在某种信仰框架内展开，不能简单等同于研究宗教的一切历史和社会现象。','Christian theology；a degree in theology；a question of theology。','religious studies 范围可含宗教史、社会学等；theology 更集中于神圣事物与教义的系统讨论。',('She studied theology before researching the history of religious education.','她先学神学，后来研究宗教教育史。'),('The debate concerned a central question in their theology.','争论涉及他们神学中的一个核心问题。'),sources=['https://www.etymonline.com/word/theology','https://en.wiktionary.org/wiki/theology#English']),
E('theological','英 /ˌθiəˈlɒdʒɪkəl/；美 /ˌθiəˈlɑːdʒɪkəl/','神学的；有关宗教教义的','在讨论信仰的理论内容，而不只是举行什么仪式。','现代可按 theology + -ical 理解；历史上有中世纪拉丁 theologicalis 经中古英语借入的形容词路线。',L+[['希腊 theología → 拉丁 theologia / theologicus → 中世纪拉丁 theologicalis','神学及其形容词形式'],['中古英语 theologicalle → 英语 theological','与神学有关的']],'a theological disagreement 可能是对救赎、神性或宗教权威的解释不同。它不必是私人关系差，也不只是典礼细节不同。','a theological debate；theological differences；theological training。','religious 更宽泛，可说行为、组织和信仰；theological 特别突出教义与理论讨论。',('The council considered the theological implications of the statement.','会议讨论了这项声明在神学上的含义。'),('Their disagreement was theological rather than personal.','他们的分歧在神学观点上，并非私人恩怨。'),sources=['https://www.etymonline.com/word/theological']),
E('theologian','英 /ˌθiəˈləʊdʒən/；美 /ˌθiəˈloʊdʒən/','神学家','把信仰中的问题拿出来，作系统分析和论述的人。','借古法语 theologien，由 theologie 形成；现代可与 theology 对照，但人物名称已有法语来源。',TH[:-1]+[['古法语 theologie → theologien → 英语 theologian','神学 → 神学研究者']],'神学家可能讨论古代宗教文本，也可能思考现代伦理问题与其信仰的关系。信仰某宗教的人，不因此自动成为 theologian。','a medieval theologian；a leading theologian；the writings of a theologian。','believer 是信徒；theologian 指神学研究和论述者，强调工作或学术角色。',('The theologian compared two interpretations of the passage.','神学家比较了对那段经文的两种解释。'),('Her lecture introduced a theologian whose work influenced later debates.','她的讲座介绍了一位影响后世争论的神学家。'),sources=['https://www.etymonline.com/word/theologian','https://en.wiktionary.org/wiki/theologian#English']),
E('mythology','英 /mɪˈθɒlədʒi/；美 /mɪˈθɑːlədʒi/','神话体系；神话学','把一个文化里关于神、英雄和世界来历的故事放在一起看。','希腊 mŷthos“故事、叙述” + 讲述成分 → mythología，经拉丁、法语进入英语。',L+[['希腊 mŷthos + -logía → mythología → 拉丁 mythologia','讲述神话、传说'],['中古法语 mythologie → 中古英语／英语 mythology','神话的集合；也指研究神话']],'Greek mythology 通常指希腊神话这一整套故事；study mythology 则可以说研究神话的工作。这里不必带“这些人说谎”的贬义，重点是故事怎样承载文化解释。','Greek mythology；comparative mythology；a figure from mythology。','myth 常是单个神话；mythology 可以是相互联系的整套故事，也可指研究领域。',('The painting draws on a familiar story from Greek mythology.','这幅画取材于希腊神话中的一个熟悉故事。'),('The course explores how mythology explains the origins of social customs.','课程探讨神话如何解释社会习俗的来历。'),sources=['https://www.etymonline.com/word/mythology','https://en.wiktionary.org/wiki/mythology#English']),
E('eulogy','/ˈjuːlədʒi/','颂词；悼词','把一个人的可贵之处讲出来，现代尤其常见于葬礼上的追念。','希腊 eu- “好” + -logia“话语”形成 eulogia；英语借拉丁 eulogium，这个拉丁形式也被分析为受到 elogium“题辞、赞辞”影响。',L+[['希腊 eu- + -logía → eulogía','好话、赞美'],['拉丁 eulogium → 英语 eulogy','赞辞；拉丁形式与 elogium 的交汇影响有讨论'],['现代常见用法','追述逝者生平与品格的悼词']],'a eulogy for someone 不只是列出生卒日期，而是讲这个人如何影响别人。历史或其他文体中也能泛指赞颂，并不是所有 eulogy 都一定在葬礼上。','deliver a eulogy；a moving eulogy；a eulogy for someone。','obituary 通常是讣告或逝者生平报道；eulogy 更突出赞颂与追念的讲话或文章。',('Her brother delivered a moving eulogy at the funeral.','她哥哥在葬礼上致了感人的悼词。'),('The eulogy recalled his patience with young colleagues.','悼词回忆了他对年轻同事的耐心。'),sources=['https://www.etymonline.com/word/eulogy','https://en.wiktionary.org/wiki/eulogy#English']),
E('chronology','英 /krəˈnɒlədʒi/；美 /krəˈnɑːlədʒi/','年代顺序；大事年表；年代学','先把事情放回时间线上，再看什么先发生、什么后发生。','希腊 chrono- “时间” + -logia；经法语 chronologie 或新拉丁 chronologia 等学术形式借入。',CH,'a chronology of events 是按时间排列的事件记录。排列正确能帮你理解过程，但“发生在后”不等于“由前一件事造成”，因果还需要额外证据。','establish the chronology；a chronology of events；a detailed chronology。','timeline 常指画出来的时间线或日程；chronology 更强调事情的时间次序及其确定。',('The letters helped establish the chronology of the expedition.','这些信件帮助确定了探险活动的时间顺序。'),('The appendix contains a chronology of major discoveries.','附录收有重要发现的年表。'),sources=['https://www.etymonline.com/word/chronology','https://en.wiktionary.org/wiki/chronology#English']),
E('chronological','英 /ˌkrɒnəˈlɒdʒɪkəl/；美 /ˌkrɑːnəˈlɑːdʒɪkəl/','按时间先后的；年代顺序的','按照事情发生的先后来排队。','英语 chronology + -ical；由时间次序的名词形成形容词。',CH+[['英语 chronology + -ical → chronological','依年代或时间先后安排的']],'chronological order 通常从早到晚；reverse chronological order 才明确说从晚到早。chronological age 是按出生日期算出的实际年龄，不是某种能力测量的年龄。','in chronological order；a chronological account；chronological age。','logical order 按推理关系排列；chronological order 按时间排列，写作时可选择不同组织方式。',('Arrange the photographs in chronological order.','把照片按拍摄时间先后排列。'),('The report gives a chronological account of the rescue.','报告按时间顺序叙述了救援过程。'),sources=['https://www.etymonline.com/word/chronological']),
E('astrology','英 /əˈstrɒlədʒi/；美 /əˈstrɑːlədʒi/','占星术','根据星体位置给人的性格或命运作解释的体系。','希腊 ástron“星” + -logia → astrología，经拉丁、法语进入英语；古时与观测天体的学问有重叠，现代意义已经分开。',L+[['希腊 astrología → 拉丁 astrologia → 中古法语 astrologie → 英语 astrology','关于星体的知识与解说'],['现代常用义','据星体位置作性格、命运等占星解释']],'看出生时的星盘，再据此解释性格，是 astrology 的典型场景。这里的 -logy 并不自动保证一个领域属于现代科学。','a belief in astrology；a book on astrology；astrology and horoscopes。','astronomy 是研究天体与宇宙的天文学；astrology 是占星解释体系。',('She reads about astrology for entertainment.','她阅读占星方面的内容作消遣。'),('The exhibit explains how astrology and astronomy developed different roles.','展览解释了占星术和天文学如何逐渐形成不同的角色。'),sources=['https://www.etymonline.com/word/astrology','https://en.wiktionary.org/wiki/astrology#English']),
E('numerology','英 /ˌnjuːməˈrɒlədʒi/；美 /ˌnuːməˈrɑːlədʒi/','数字命理学；数字神秘论','把姓名、生日等换成数字，再给这些数字赋予命运含义。','近代 numero- “数字” + -logy；numero- 接拉丁 numerus，后半是希腊来源，属于混合构词。',L+[['拉丁 numerus〔数〕→ numero- + 希腊来源 -logy','借古典语言材料组成近代英语词'],['英语 numerology','以数字解释性格、命运等的神秘论体系']],'这里的数字被赋予象征或预测意义，和用严格证明研究整数性质不是一回事。不能看到 -logy 就直接理解成一门实证科学。','a system of numerology；a book on numerology；numerology based on birth dates。','number theory 是数学的数论；numerology 是数字神秘解释，两者不要互译。',('The article describes a form of numerology based on names.','文章介绍了一种以姓名为依据的数字命理体系。'),('The exhibition distinguishes mathematical symbolism from numerology.','展览区分了数学符号体系与数字神秘论。'),sources=['https://en.wiktionary.org/wiki/numerology#English','https://www.etymonline.com/word/numerology']),
E('phenomenology','英 /fɪˌnɒmɪˈnɒlədʒi/；美 /fɪˌnɑːməˈnɑːlədʒi/','现象学','仔细看经验是怎样呈现在意识中的，而不急着先给它套解释。','希腊 phainómenon“显现之物” + -logy；近代德语 Phänomenologie 等哲学用法形成并传播，不能把整个学科名称倒推为古希腊已有。',L+[['希腊 phainómenon〔显现的东西〕+ -logia → 近代哲学术语','讨论事物如何显现；术语早于胡塞尔的现象学运动'],['德语 Phänomenologie 等 → 英语 phenomenology','后来尤其指对经验结构的哲学研究']],'听一段旋律时，你不只听到眼前一个音，还保留刚过去的音并期待后续。现象学会研究这种经验结构。不同哲学家的方法并不完全相同，不能只用“研究所有现象”概括。','the phenomenology of perception；a course in phenomenology；Husserl’s phenomenology。','psychology 可用实验等方法研究心理；phenomenology 在这里是哲学方法和传统，关注经验怎样被体验。',('The seminar used a melody to discuss the phenomenology of time.','研讨课用一段旋律讨论时间经验的现象学。'),('Her essay examines the phenomenology of feeling at home in a place.','她的文章从现象学角度分析了在一个地方产生归属感的经验。'),sources=['https://plato.stanford.edu/entries/phenomenology/','https://www.etymonline.com/word/phenomenology']),
E('ecclesiology','英 /ɪˌkliːziˈɒlədʒi/；美 /ɪˌkliːziˈɑːlədʒi/','教会论；教会建筑研究〔另一用法〕','教会可以是一群信众组成的共同体，也可以落实为建筑；这个词的两种用法围绕这两面展开。','后期拉丁 ecclesia“教会”来自希腊 ekklēsía“集会”；近代再加连接元音 -o- 与 -logy。',[['希腊 ekklēsía〔集会〕→ 后期拉丁 ecclesia〔教会〕；另一路 lógos〔论述〕', '前者提供教会含义，后者是 -logy 的来源；两路材料在近代组合'], ['近代 ecclesio- + -logy → ecclesiology', '研究教会的性质；也曾特别指教堂建筑、装饰研究']],'神学中讨论“教会是什么、权威从哪里来”，属于教会论。建筑史文章里的 ecclesiology 可能关注教堂的设计与陈设；先看文体再选译法。','a question of ecclesiology；the study of ecclesiology；medieval ecclesiology。','theology 范围更广；ecclesiology 集中在教会，而建筑研究义不能误译成纯粹的教义讨论。',('The theologian’s ecclesiology places great emphasis on the local congregation.','这位神学家的教会论非常重视地方教会共同体。'),('The archive contains nineteenth-century studies of ecclesiology and church decoration.','档案保存着十九世纪关于教堂建筑及其装饰的研究。'),sources=['https://www.merriam-webster.com/dictionary/ecclesiology','https://en.wiktionary.org/wiki/ecclesiology#English']),
E('eschatology','英 /ˌeskəˈtɒlədʒi/；美 /ˌeskəˈtɑːlədʒi/','末世论；终极事物的宗教论述','追问死亡、审判、来世以及世界最终结局等问题。','希腊 éskhatos“最后的、最远的” + -logy，构成近代神学术语。',L+[['希腊 éskhatos〔最后的〕→ eschato- + -logy','以最后、终极事物为讨论对象'],['英语 eschatology','关于死亡、来世及终极结局的宗教教义研究']],'它并不只指预测某年世界末日，也包括宗教怎样理解个人死后的命运。不同传统的末世论内容差异很大。','Christian eschatology；a study of eschatology；eschatology and the afterlife。','prediction 是一般预测；eschatology 是有关终极结局的一组宗教观念与研究。',('The course compares ideas about judgment in different traditions of eschatology.','课程比较了不同末世论传统中的审判观念。'),('Her chapter connects eschatology with beliefs about the afterlife.','她的章节把末世论与来世信仰联系起来讨论。'),sources=['https://www.etymonline.com/word/eschatology','https://en.wiktionary.org/wiki/eschatology#English']),
E('demonology','英 /ˌdiːməˈnɒlədʒi/；美 /ˌdiːməˈnɑːlədʒi/','恶魔学；关于恶魔的信仰与论述','整理某种传统怎样想象、命名和解释恶魔。','demon + -ology；demon 经拉丁接希腊 daímōn“神灵、灵性存在”，其较早含义不总是邪恶。',[['希腊 daímōn → 拉丁 daemon → 英语 demon；另一路希腊 lógos', '前者指神灵、后常指恶魔；后者提供论述与研究的构词材料'], ['英语 demon + -ology → demonology', '关于恶魔的论述、传统或研究']],'历史学家研究一部 demonology，可以是在研究当时人们的恐惧与信仰，并不是在承认书中生物真实存在。这个词也可说某传统整套恶魔观念。','medieval demonology；a treatise on demonology；the history of demonology。','mythology 范围可包含众多神话人物；demonology 专注恶魔观念和相关叙述。',('The historian read the book as evidence of early modern demonology.','历史学家把这本书当作近代早期恶魔观念的证据来读。'),('The exhibition explores how demonology shaped the imagery in old prints.','展览探讨了恶魔学观念如何影响旧版画中的形象。'),sources=['https://www.etymonline.com/word/demonology']),
E('musicology','英 /ˌmjuːzɪˈkɒlədʒi/；美 /ˌmjuːzɪˈkɑːlədʒi/','音乐学','不只把音乐演出来，还研究它怎样写成、流传和被人理解。','英语 music + -ology；music 经法语、拉丁接希腊 mousikḗ“缪斯的艺术”，再与研究领域后缀组合。',[['希腊 mousikḗ → 拉丁 musica → 古法语 musique → 英语 music；另一路 lógos', '音乐名称与研究后缀的词源相互独立，到近代才组合'], ['英语 music + -ology → musicology', '音乐的历史、理论与文化研究']],'比较作曲家的草稿、研究一种演唱传统如何传承，都可能是音乐学工作。会演奏很有帮助，但 musicology 不是“乐器演奏课”的另一个名字。','historical musicology；a degree in musicology；research in musicology。','performance 强调实际演出；musicology 强调研究音乐，两者可以相互支持。',('Her research in musicology compares the composer’s surviving drafts.','她的音乐学研究比较了这位作曲家留存的草稿。'),('The department offers courses in musicology as well as performance.','系里既开设音乐学课程，也开设表演课程。'),sources=['https://www.etymonline.com/word/musicology','https://en.wiktionary.org/wiki/musicology#English']),
E('criminology','英 /ˌkrɪmɪˈnɒlədʒi/；美 /ˌkrɪmɪˈnɑːlədʒi/','犯罪学','研究犯罪怎样发生、呈现什么规律，以及社会怎样回应。','拉丁 crimen 的词干 crimin- “罪、指控” + 希腊来源 -ology，形成近代学科名称。',L+[['拉丁 crimen／crimin-〔罪、指控〕+ -ology','使用拉丁与希腊材料的近代组合'],['英语 criminology','关于犯罪及社会应对的系统研究']],'它可以比较不同地区的犯罪变化，也可以研究刑罚、预防措施与社会条件。范围远超过现场找指纹，不等同于侦探技巧。','a degree in criminology；research in criminology；criminology and criminal justice。','forensic science 用科学方法分析案件证据；criminology 更广泛地研究犯罪及其社会背景。',('The criminology class examined changes in reported crime over twenty years.','犯罪学课堂分析了二十年间报案犯罪情况的变化。'),('Her research in criminology focuses on how communities respond to youth crime.','她的犯罪学研究关注社区如何应对青少年犯罪。'),sources=['https://www.etymonline.com/word/criminology','https://en.wiktionary.org/wiki/criminology#English']),
E('ethnology','英 /eθˈnɒlədʒi/；美 /eθˈnɑːlədʒi/','民族学；比较文化研究','把不同人群的文化、制度和历史放在一起比较。','希腊 éthnos“人群、民族” + -logy；近代英语构词也与法语、德语的对应学术名称有关。',L+[['希腊 éthnos〔人群、民族〕+ -logia → 近代欧洲学术术语','比较不同人群的文化与历史'],['英语 ethnology','民族学；比较研究文化和社会组织']],'它可以比较亲属制度、迁徙故事或社会习俗。研究的是人群的文化与关系，不能把它理解成给所谓“种族”排高低等级。','comparative ethnology；a museum of ethnology；research in ethnology。','ethnography 常重具体群体的深入观察与描述；ethnology 常突出比较分析，两种工作相互联系。',('The museum’s ethnology collection includes objects used in everyday work.','博物馆的民族学藏品包括日常劳动用具。'),('Her study in ethnology compares kinship systems across several communities.','她的民族学研究比较了几个社区的亲属制度。'),sources=['https://www.etymonline.com/word/ethnology','https://www.merriam-webster.com/dictionary/ethnology'])
])
BIO=L+[['希腊 bíos〔生命〕+ -logía → 新拉丁 biologia','近代学术造词：研究生命'],['英语 biology','研究生物及生命过程；名称经近代科学用法逐渐固定']]
ECO=L+[['希腊 oîkos〔家、住所〕+ -logía → 德语 Ökologie','Haeckel 于十九世纪用古典材料命名生物与环境的关系研究'],['英语 ecology','仿借德语术语；研究生物彼此及其环境的关系']]
MOR=L+[['希腊 morphḗ〔形态〕+ -logía → 德语 Morphologie','近代把形态作为系统研究对象'],['英语 morphology','借入后用于生物形态及语言中的词形结构等领域']]
ZOO=L+[['希腊 zōîon〔动物〕+ -logía → 新拉丁 zoologia','近代学术词：动物研究'],['英语 zoology','动物学']]
GEO=L+[['希腊 gē / geō-〔地球〕+ -logia → 新拉丁 geologia','关于地球的研究名称'],['英语 geology','地球的物质、结构、过程与历史研究']]
W.extend([
E('biology','英 /baɪˈɒlədʒi/；美 /baɪˈɑːlədʒi/','生物学；某种生物的生命特征','从一个细胞怎样工作，一直问到生命怎样繁衍和演化。','bio- “生命” + -logy；整词经新拉丁 biologia 等近代学术用法进入英语，不是古希腊已经存在的现代学科名称。',BIO,'生物学并不只背动物和植物的名字，还研究结构、功能、遗传、环境关系等。the biology of a species 则是说某物种怎样生长、生活和繁殖。','study biology；molecular biology；the biology of a species。','biography 是人的生平记述；biology 是生命科学，同有 bio-，后半的任务不同。',('Our biology lesson began with cells dividing under a microscope.','我们的生物课从显微镜下的细胞分裂开始。'),('Understanding the insect’s biology helped explain its seasonal appearance.','了解这种昆虫的生物学特征，有助于解释它为什么在特定季节出现。'),sources=['https://en.wiktionary.org/wiki/biology#English']),
E('biological','英 /ˌbaɪəˈlɒdʒɪkəl/；美 /ˌbaɪəˈlɑːdʒɪkəl/','生物的；生物学的；有血缘关系的','把原因、过程或关系放到生命活动这一层来看。','英语 biology + -ical；重音从名词前部移到 -log-。',BIO+[['英语 biology + -ical → biological','生物学相关的；由生命过程形成的']],'a biological process 可以是发酵或细胞分裂。biological parents 说生育或遗传关系，并不评价谁实际照顾、养育孩子。','biological processes；biological diversity；biological parents。','biological 说生命或血缘层面；social 说社会关系，两者可以同时影响一个问题。',('The study examines the biological processes involved in fermentation.','研究分析了发酵涉及的生物过程。'),('She met her biological father as an adult.','她成年后见到了自己的生父。')),
E('biologically','英 /ˌbaɪəˈlɒdʒɪkli/；美 /ˌbaɪəˈlɑːdʒɪkli/','从生物学上看；通过生物过程','明确告诉你：这里是在生命机制或遗传关系这一层面说话。','biological + -ly；形容词转为说明方式或判断角度的副词。',BIO+[['英语 biology → biological → biologically','生物学 → 从生物学层面而言']],'biologically related 常说有血缘关系；biologically active 则可形容一种物质会对生物系统产生作用。它不等于“天然所以安全”。','biologically related；biologically active；biologically important。','biologically 是判断角度或作用方式；naturally 可能只是说自然发生，二者不总能互换。',('The two children are biologically related but grew up in different homes.','这两个孩子有血缘关系，却在不同家庭长大。'),('The researchers measured whether the compound remained biologically active.','研究者测量了这种化合物是否仍具有生物活性。')),
E('biologic','英 /ˌbaɪəˈlɒdʒɪk/；美 /ˌbaɪəˈlɑːdʒɪk/','生物学的；生物制剂〔名词〕','形容词谈生命过程；作名词时，常指利用生物来源或生物系统制成的药用产品。','biology + -ic；后来形容词转用为名词，通常对应 biological product，不能把名词只译成“生物”。',BIO+[['英语 biology + -ic → biologic','生物的、生物学的'],['名词 biologic，复数 biologics','生物制品、生物制剂']],'生物制剂可包括疫苗、抗体等不同产品，不是一个单一药物名称。日常一般形容“生物学的”时 biological 更常见；药品讨论中的 a biologic 则是名词。','a biologic medicine；biologic activity；the manufacture of biologics。','biologic 与 biological 可在形容词用法中接近；a biologic 是产品名称，不能随意删去冠词当学科名。',('The laboratory measured the compound’s biologic activity.','实验室测量了这种化合物的生物活性。'),('The facility manufactures a biologic using cultured cells.','这家工厂利用培养的细胞生产一种生物制剂。'),sources=['https://en.wiktionary.org/wiki/biologic#English','https://www.fda.gov/about-fda/center-biologics-evaluation-and-research-cber/what-are-biologics-questions-and-answers']),
E('biologist','英 /baɪˈɒlədʒɪst/；美 /baɪˈɑːlədʒɪst/','生物学家','用观察和实验研究生命怎样运作的人。','英语 biology + -ist；学科名转为研究者名称。',BIO+[['英语 biology + -ist → biologist','生物学研究者']],'有人在实验室研究细胞，有人在野外跟踪动物。biologist 范围很宽，不能一律想成穿白衣、拿试管的人。','a marine biologist；a field biologist；a molecular biologist。','doctor 常指医生或博士；biologist 指研究领域，生物学家并不因此具有临床行医身份。',('The biologist recorded how the frogs responded to changes in temperature.','生物学家记录了青蛙对温度变化的反应。'),('A marine biologist joined the team studying the reef.','一位海洋生物学家加入了珊瑚礁研究团队。')),
E('microbiology','英 /ˌmaɪkrəʊbaɪˈɒlədʒi/；美 /ˌmaɪkroʊbaɪˈɑːlədʒi/','微生物学','把研究视线缩小，去看细菌、微小真菌等肉眼难见的对象及其活动。','micro- “微小” + biology；微小的是研究对象，并不是“小规模做一点生物学”。',BIO+[['英语 micro- + biology → microbiology','以微生物及相关对象为中心的生物学研究']],'它既研究致病微生物，也研究发酵、土壤养分循环等过程。领域中也包含病毒研究，因此不要用“是否独立存活”简单划掉所有病毒相关工作。','food microbiology；a microbiology laboratory；research in microbiology。','microbiology 范围比 bacteriology 广；后者专门研究细菌。',('The microbiology team studied the organisms involved in making yogurt.','微生物学团队研究了制作酸奶时参与发酵的微生物。'),('The water samples were sent to the microbiology laboratory.','水样被送往微生物实验室。')),
E('neurobiology','英 /ˌnjʊərəʊˌbaɪˈɒlədʒi/；美 /ˌnʊroʊˌbaɪˈɑːlədʒi/','神经生物学','把神经系统当作活的细胞和网络，研究它怎样发育、传信和改变。','neuro- “神经” + biology；neuro- 接希腊 neûron，早期可指筋、腱，科学词中专指神经。',BIO+[['希腊 neûron → 近代 neuro- + 英语 biology → neurobiology','研究神经系统的生物机制']],'研究突触如何传递信号、神经细胞如何连接，都属于这个领域。它可以帮助理解行为，但不等于只凭脑扫描就能读出一个人的所有想法。','cellular neurobiology；developmental neurobiology；the neurobiology of learning。','neurology 常指诊治神经系统疾病的临床专科；neurobiology 更突出基础生命机制研究。',('The course in neurobiology explains how neurons communicate.','神经生物学课程解释了神经元如何传递信息。'),('Her laboratory studies the neurobiology of learning.','她的实验室研究学习的神经生物学机制。'),sources=['https://en.wiktionary.org/wiki/neurobiology#English','https://www.oxfordlearnersdictionaries.com/definition/english/neurobiology']),
E('astrobiology','英 /ˌæstrəʊbaɪˈɒlədʒi/；美 /ˌæstroʊbaɪˈɑːlədʒi/','天体生物学；宇宙生命研究','把“生命怎样出现、能在哪里存在”这个问题，放到整个宇宙的背景里。','astro- “星体、宇宙” + biology；现代交叉学科构词，不是“只研究恒星上的生物”。',BIO+[['英语 astro- + biology → astrobiology','研究宇宙中生命的起源、演化、分布与可能环境']],'研究地球极端环境里的微生物，也可能属于天体生物学，因为它帮助判断别处什么条件可能适合生命。这个领域的存在，不表示已经找到了地外生命。','research in astrobiology；an astrobiology mission；questions in astrobiology。','astronomy 研究天体与宇宙；astrobiology 把生命问题带入其中，并结合地球上的生物证据。',('The astrobiology project studies microbes that survive in very salty water.','这个天体生物学项目研究能在高盐水中生存的微生物。'),('Astrobiology connects the search for habitable planets with research on life’s origins.','天体生物学把寻找宜居行星与生命起源研究联系起来。'),sources=['https://en.wiktionary.org/wiki/astrobiology#English','https://science.nasa.gov/astrobiology/at-nasa/','https://www.nasa.gov/ames/core-area-of-expertise-biology-and-astrobiology/']),
E('ecology','英 /ɪˈkɒlədʒi/；美 /iˈkɑːlədʒi/，亦 /ɪˈkɑːlədʒi/','生态学；生态关系','把生物放回它生活的“家”，看它跟邻居和环境怎样相互影响。','eco- 来自希腊 oîkos“住所”，-logy 是研究；英语仿借十九世纪德语 Ökologie。',ECO,'森林里谁吃谁、树木怎样影响光线、温度怎样改变物种分布，都是生态问题。ecology 既可指学科，也可指某地这套生物与环境关系。','forest ecology；the ecology of a river；a course in ecology。','environment 是环境；ecology 强调环境与生物之间的关系，并不等于泛泛的“环保”。',('The project examines how flooding changes the ecology of the riverbank.','项目研究洪水怎样改变河岸的生态关系。'),('She studies ecology with a focus on interactions between plants and insects.','她研究生态学，重点关注植物和昆虫之间的相互作用。'),sources=['https://en.wiktionary.org/wiki/ecology#English','https://www.etymonline.com/word/ecology']),
E('ecological','英 /ˌiːkəˈlɒdʒɪkəl/；美 /ˌiːkəˈlɑːdʒɪkəl/','生态的；生态学的','看一个变化怎样牵动生物和环境之间的关系。','英语 ecology + -ical；常用来描述系统、影响、研究或关系。',ECO+[['英语 ecology + -ical → ecological','与生态关系或生态学有关的']],'an ecological impact 可能改变食物网、栖息地或物种竞争。ecological 本身并不自动等于“对环境有益”，破坏也有生态影响。','ecological impact；ecological research；an ecological relationship。','environmentally friendly 是有利于环境的评价；ecological 只是说明涉及生态，可以是好影响也可以是坏影响。',('The team assessed the ecological impact of the new road.','团队评估了新道路的生态影响。'),('The field course teaches students how to collect ecological data.','野外课程教学生怎样收集生态数据。')),
E('morphology','英 /mɔːˈfɒlədʒi/；美 /mɔːrˈfɑːlədʒi/','形态学；词法、词形学〔语言学〕','研究一个东西的形态怎样组成；在语言里，就把镜头对准单词的内部。','借德语 Morphologie，以希腊 morphḗ“形态” + -logia 组成；后来扩展到语言学等领域。',MOR,'生物学可以比较叶片或骨骼的形状；语言学则研究词根、词缀、词形变化怎样构成词。cats 的复数 -s 是词形问题，两个句子怎样连接则不主要属于这一层。','plant morphology；word morphology；the morphology of a language。','syntax 研究词怎样组成句子；morphology 研究词的内部结构，边界在不同理论中会有讨论。',('The botanist compared the morphology of leaves from the two species.','植物学家比较了两个物种叶片的形态。'),('The lesson on morphology explains why “walked” contains a past-tense ending.','词形学课解释了 walked 为什么含有过去时词尾。'),sources=['https://en.wiktionary.org/wiki/morphology#English','https://www.etymonline.com/word/morphology']),
E('morphological','英 /ˌmɔːfəˈlɒdʒɪkəl/；美 /ˌmɔːrfəˈlɑːdʒɪkəl/','形态的；词形的','关注形状或内部构成这一面，而不是所有性质一起说。','英语 morphology + -ical；具体指生物形态还是词形，要看对象。',MOR+[['英语 morphology + -ical → morphological','有关形态或词形结构的']],'morphological differences 可以是两个物种的身体结构差异，也可以是两种语言构词方式不同。看到这个词先问：研究的是生物，还是语言？','morphological features；morphological analysis；morphological differences。','phonological 关注语言声音系统；morphological 关注词的结构，字音和构词可能互相影响。',('The two species share several morphological features.','这两个物种有几项共同的形态特征。'),('A morphological analysis separates the prefix from the base word.','词形分析把前缀和词基区分开来。')),
E('morphologically','英 /ˌmɔːfəˈlɒdʒɪkli/；美 /ˌmɔːrfəˈlɑːdʒɪkli/','在形态上；从词形结构看','把比较范围限定为形态或词的组成方式。','morphological + -ly；用来修饰相似、不同、复杂等判断。',MOR+[['英语 morphology → morphological → morphologically','形态研究 → 从形态或词形方面看']],'morphologically similar 只说形态相近，不能单凭这一点断言两个生物就是同一物种。morphologically complex 说词含有多个构词成分，并不一定说它难懂。','morphologically similar；morphologically distinct；morphologically complex。','genetically 说遗传层面；morphologically 说形态层面，结论可能相同也可能不同。',('The larvae are morphologically similar but belong to different species.','这些幼虫在形态上相似，却属于不同物种。'),('The word is morphologically complex because it contains two prefixes and a suffix.','这个词在构词上较复杂，因为它含有两个前缀和一个后缀。')),
E('zoology','英 /zəʊˈɒlədʒi/；美 /zoʊˈɑːlədʒi/；亦有 /zuː-/ 起读','动物学','研究动物怎样构成、生活、繁殖和演化。','希腊 zōîon“动物” + -logia 形成新拉丁 zoologia，再借入英语；不是动物园 zoo 加一个学科后缀的原始历史。',ZOO,'从微小无脊椎动物到大型哺乳动物都在范围内。动物园只是可能开展相关工作的地点之一，野外、实验室和博物馆同样重要。','marine zoology；a degree in zoology；the study of zoology。','biology 包括生命研究的更大范围；zoology 集中研究动物，botany 则研究植物。',('She studied zoology before joining a marine research centre.','她先学动物学，后来加入海洋研究中心。'),('The zoology collection includes specimens of insects and mammals.','动物学藏品包括昆虫和哺乳动物标本。'),sources=['https://www.etymonline.com/word/zoology','https://en.wiktionary.org/wiki/zoology#English']),
E('zoological','英 /ˌzəʊəˈlɒdʒɪkəl/；美 /ˌzoʊəˈlɑːdʒɪkəl/','动物学的；有关动物研究的','给研究、标本或机构标明：这里围绕动物展开。','英语 zoology + -ical；zoological garden 后来缩略为 zoo，所以不能把历史顺序倒写。',ZOO+[['英语 zoology + -ical → zoological','动物学的；zoological garden 后来有缩略词 zoo']],'a zoological survey 调查某地动物，a zoological collection 保存相关标本。这个词不只用于活体动物展览。','a zoological survey；a zoological collection；a zoological garden。','zoological 是动物学方面的；ecological 关注生物与环境关系，一次调查可以兼具两种方向。',('The museum moved its zoological collection to a new building.','博物馆把动物学藏品搬到了新楼。'),('A zoological survey recorded several species previously unknown on the island.','一次动物调查记录了岛上此前未被记录的几个物种。')),
E('zoologist','英 /zəʊˈɒlədʒɪst/；美 /zoʊˈɑːlədʒɪst/','动物学家','通过观察和研究，弄清动物怎样生活的人。','英语 zoology + -ist；职业名称来自学科名，不是“动物园管理员”的构词。',ZOO+[['英语 zoology + -ist → zoologist','动物学研究者']],'一位 zoologist 可以研究昆虫交配、海兽迁徙或动物分类。是否在动物园工作，与这个研究身份不是一回事。','a field zoologist；a marine zoologist；a team of zoologists。','zookeeper 负责动物园里的饲养与照护；zoologist 强调动物研究，两种角色可能合作。',('The zoologist tracked the animals without disturbing their nesting sites.','动物学家在不打扰巢址的情况下追踪这些动物。'),('A zoologist identified the unusual specimen in the museum.','一位动物学家鉴定了博物馆里的特殊标本。')),
E('entomology','英 /ˌentəˈmɒlədʒi/；美 /ˌentəˈmɑːlədʒi/','昆虫学','把注意力集中到昆虫的身体、生活史和生态关系上。','借法语 entomologie，由希腊 éntomon“昆虫” + -logie 组成；éntomon 原与“切开的、分节的”身体外观有关。',L+[['希腊 éntomon〔分节状的昆虫〕+ -logie → 法语 entomologie','用身体分节的形象命名昆虫研究'],['英语 entomology','昆虫学']],'研究蚂蚁如何协作、蝴蝶幼虫吃什么，都属于昆虫学。日常把许多小爬虫都叫虫，科学上的 insect 却有具体范围。','agricultural entomology；a collection for entomology；research in entomology。','etymology 是词源学；entomology 多了昆虫成分 entomo-，不要凭轮廓看错。',('Her interest in entomology began with watching ants in the garden.','她对昆虫学的兴趣始于观察花园里的蚂蚁。'),('The entomology laboratory studies insects that pollinate crops.','昆虫学实验室研究给农作物授粉的昆虫。'),sources=['https://en.wiktionary.org/wiki/entomology#English','https://www.etymonline.com/word/entomology']),
E('ornithology','英 /ˌɔːnɪˈθɒlədʒi/；美 /ˌɔːrnɪˈθɑːlədʒi/','鸟类学','研究鸟怎样飞、迁徙、繁殖，以及彼此怎样区分。','新拉丁 ornithologia 接希腊 órnis、词干 ornith- “鸟”及讲述、研究成分，再借入英语。',L+[['希腊 órnis／ornith-〔鸟〕及 ornithológos → 新拉丁 ornithologia','把鸟类作为研究对象的学术名称'],['英语 ornithology','鸟类学']],'观鸟可以提供记录，鸟类学则进一步提出问题、整理证据和检验解释。工作也可能研究鸟鸣、遗传或栖息地，不只辨认羽毛颜色。','field ornithology；a journal of ornithology；research in ornithology。','birdwatching 是观鸟活动；ornithology 是研究领域，爱好者的观察也可能贡献科学数据。',('The ornithology course includes training in identifying birds by their calls.','鸟类学课程包括通过叫声识别鸟类的训练。'),('Long-term records of migration are valuable for ornithology.','长期迁徙记录对鸟类学很有价值。'),sources=['https://en.wiktionary.org/wiki/ornithology#English']),
E('ethology','英 /iːˈθɒlədʒi/；美 /iˈθɑːlədʒi/，亦 /ɪˈθɑːlədʒi/','动物行为学','看动物实际怎样行动，再问这种行为有什么作用、怎样形成。','希腊 êthos“性格、习性”形成 ēthologia，经拉丁借入；早期有描绘、模仿性格义，后来发展出动物行为研究义。',L+[['希腊 ēthología → 拉丁 ethologia → 英语 ethology','描绘、模仿性格；后来有性格形成研究义'],['近现代动物学用法','研究动物行为及其形成机制与功能']],'鸟为什么求偶展示、动物怎样学习路线，都可以是行为学问题。研究常重视自然环境，也会做实验，并不只是把动物行为拟人化讲故事。','animal ethology；a study in ethology；the history of ethology。','ethnology 研究人群文化；ethology 在现代主要研究动物行为，中间没有 n。',('The ethology project examines how young birds learn their songs.','动物行为学项目研究幼鸟怎样学习鸣唱。'),('The lecture on ethology used courtship displays as an example.','动物行为学讲座以求偶展示为例作了说明。'),sources=['https://www.etymonline.com/word/ethology','https://en.wiktionary.org/wiki/ethology#English']),
E('embryology','英 /ˌembriˈɒlədʒi/；美 /ˌembriˈɑːlədʒi/','胚胎学','研究早期生命怎样从细胞一步步形成组织和身体结构。','英语 embryo + -logy；embryo 经拉丁接希腊 émbryon，带有“在里面生长”的历史画面。',[['希腊 émbryon → 拉丁 embryo → 英语 embryo；另一路 lógos', '胚胎名称与论述、研究后缀分别提供材料'], ['英语 embryo + -logy → embryology', '对胚胎形成和发育过程的研究']],'它研究细胞何时分化、器官怎样形成，也比较不同动物的发育过程。研究对象不是一个缩小版的完整成体，而是持续变化的发育系统。','comparative embryology；a course in embryology；early embryology research。','anatomy 着重身体结构；embryology 特别问这些结构在早期怎样形成。',('The embryology class followed the formation of the nervous system.','胚胎学课追踪了神经系统的形成过程。'),('Comparative embryology examines similarities and differences in early development.','比较胚胎学研究早期发育的异同。'),sources=['https://en.wiktionary.org/wiki/embryology#English','https://www.oxfordlearnersdictionaries.com/definition/english/embryology']),
E('gerontology','英 /ˌdʒerɒnˈtɒlədʒi/；美 /ˌdʒerənˈtɑːlədʒi/','老年学；衰老研究','把“人怎样变老、老年生活怎样变化”当成一个完整问题来研究。','希腊 gérōn、词干 geront- “老人” + -logy，形成近代学科名称。',[['希腊 gérōn／geront-〔老人〕与 lógos〔论述〕', '两个独立来源，分别贡献研究对象与学科后缀'], ['近代 geront- + -logy', '用古典材料命名老龄与衰老研究'], ['英语 gerontology', '涵盖生物、心理、社会等层面的老年学']],'研究记忆随年龄怎样变化、退休如何影响生活，或细胞如何老化，都可与老年学有关。它的范围不限于给老年患者看病。','social gerontology；research in gerontology；a gerontology programme。','geriatrics 是老年医学，集中于老年人的医疗；gerontology 是更广的衰老与老龄研究。',('The gerontology programme includes courses on housing and social support.','老年学课程项目包含住房与社会支持方面的课程。'),('Her research in gerontology follows changes in daily activity over time.','她的老年学研究长期追踪日常活动的变化。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/gerontology','https://en.wiktionary.org/wiki/gerontology#English']),
E('geology','英 /dʒiˈɒlədʒi/；美 /dʒiˈɑːlədʒi/','地质学；某地的地质状况','把岩石、地层和地形当作线索，读地球怎样变成今天这样。','geo- “地球” + -logy；受新拉丁 geologia 等学术形式影响，成为英语的地质学名称。',GEO,'the geology of an island 可以指它有哪些岩石、断层和形成过程；study geology 则是研究这些问题的学科。它不只研究矿产，也涉及地球内部和漫长历史。','study geology；the geology of the region；structural geology。','geography 更关注地表空间及自然、人文分布；geology 更突出地球物质、结构和演变，两者会相交。',('The cliffs reveal important clues about the island’s geology.','悬崖揭示了这座岛地质状况的重要线索。'),('She chose geology because she wanted to understand how mountains form.','她选择地质学，因为想弄清山脉怎样形成。'),sources=['https://en.wiktionary.org/wiki/geology#English','https://www.etymonline.com/word/geology']),
E('geological','英 /ˌdʒiːəˈlɒdʒɪkəl/；美 /ˌdʒiːəˈlɑːdʒɪkəl/','地质的；地质学的','把观察放到地球的岩石、结构和漫长变化过程里。','现代可按 geology + -ical 理解；词史也分析为新拉丁 geologia 加 -ical，形容词在英语中见于名词之前，不强行画成英语名词先产生。',L+[['希腊 geō- + -logia → 新拉丁 geologia','地球研究的学术名称'],['geologia + 英语 -ical → geological','地质的；现代与 geology 形成名词、形容词对应']],'geological time 说的是地球历史的时间尺度；geological evidence 可以来自地层、岩石或构造。它不等于“很久以前”的随意夸张，而有具体科学背景。','geological time；geological evidence；a geological survey。','geological 与 geologic 多数情况意义相近；geographical 则通常说地理空间及分布。',('The rock layers preserve a record of geological change.','这些岩层保存着地质变化的记录。'),('The team conducted a geological survey before planning the tunnel.','团队在规划隧道之前进行了地质勘查。'),sources=['https://en.wiktionary.org/wiki/geological#English','https://www.etymonline.com/word/geological']),
E('geologic','英 /ˌdʒiːəˈlɒdʒɪk/；美 /ˌdʒiːəˈlɑːdʒɪk/','地质的；地质学的','用较短的形容词形式，描述地球物质和历史过程。','英语 geology + -ic，也可能受法语 géologique 影响；不是 geology 的另一种名词拼法。',GEO+[['英语 geology + -ic → geologic','地质学相关的形容词']],'geologic map 标出岩层等地质信息；geologic time scale 把地球历史划分为有名称的时间单位。美式专业写作中这种短形式尤其常见。','a geologic map；geologic time；geologic processes。','geologic 与 geological 通常不构成严格意义对立，按固定搭配和文体选择即可。',('The geologic map shows the fault crossing the valley.','地质图显示断层穿过山谷。'),('Erosion is one of the geologic processes shaping the coast.','侵蚀是塑造海岸的地质过程之一。'),sources=['https://en.wiktionary.org/wiki/geologic#English']),
E('geologist','英 /dʒiˈɒlədʒɪst/；美 /dʒiˈɑːlədʒɪst/','地质学家；地质工作者','从岩石和地层留下的痕迹，推断地球发生过什么的人。','英语 geology + -ist，指从事地质研究或相关专业工作的人。',GEO+[['英语 geology + -ist → geologist','地质研究者']],'野外敲岩石只是工作的一面，还会分析样品、制作地图、建立模型。研究者可能关注火山、地下水、古环境等不同问题。','a field geologist；a consulting geologist；a team of geologists。','archaeologist 研究人类过去的遗存；geologist 研究地球物质与过程，挖土并不能决定是哪一行。',('The geologist collected samples from both sides of the fault.','地质学家从断层两侧采集了样品。'),('A geologist explained why the two hills contain different rocks.','一位地质学家解释了两座山丘为何含有不同岩石。')),
E('petrology','英 /pɪˈtrɒlədʒi/；美 /pəˈtrɑːlədʒi/','岩石学','不只认出这是什么石头，还追问它由什么组成、怎样形成和改变。','petro- 来自希腊 pétra“岩石”，加 -logy；不是英语 petrol“汽油”去掉一个字母。',L+[['希腊 pétra〔岩石〕→ petro- + -logy','以岩石为研究对象的近代构词'],['英语 petrology','研究岩石成分、结构、起源与变化']],'一块火成岩的矿物和结晶结构，可以提示岩浆冷却时发生的过程。岩石学属于地质学的一部分，并不限于石油相关问题。','igneous petrology；metamorphic petrology；a course in petrology。','mineralogy 研究矿物；petrology 研究由矿物等组成的岩石及其形成过程。',('The petrology course begins with the minerals found in common rocks.','岩石学课程从常见岩石中的矿物讲起。'),('Her research in petrology examines how the magma cooled.','她的岩石学研究分析岩浆如何冷却。'),sources=['https://en.wiktionary.org/wiki/petrology#English']),
E('seismology','英 /saɪzˈmɒlədʒi/；美 /saɪzˈmɑːlədʒi/；亦有 /saɪs-/ 起读','地震学','通过地震及其波动，研究地面为什么震动，也探查地下看不见的结构。','seismo- 来自希腊 seismós“震动、地震”，加 -logy，形成现代研究名称。',L+[['希腊 seismós〔震动、地震〕→ seismo- + -logy','用震动现象命名研究领域'],['英语 seismology','地震与地震波的研究']],'比较地震波何时到达不同台站，可以帮助定位震源；波怎样穿过地下，也能透露地球内部结构。这个领域不等于能准确预报每一次地震的时间。','research in seismology；global seismology；a seismology laboratory。','seismography 强调震动记录；seismology 是对地震及相关波动的更广研究。',('The seismology team compared signals from several recording stations.','地震学团队比较了几个观测站的信号。'),('Seismology provides evidence about structures deep inside the Earth.','地震学为地球深部结构提供了证据。'),sources=['https://en.wiktionary.org/wiki/seismology#English','https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes','https://www.usgs.gov/media/images/p-wave-and-s-wave-paths-through-earth']),
E('metrology','英 /meˈtrɒlədʒi/；美 /meˈtrɑːlədʒi/','计量学；测量科学','让不同地方的“一个千克”或“一个伏特”能可靠对上，并说清测量有多大不确定性。','借法语 métrologie，接希腊 metrología“比例理论”，由 métron“尺度、测量”与 -logia 构成。现代可以按 metro- + -logy 理解，但不能省略实际的法语中介。',L+[['希腊 métron + -logia → metrología','度量、比例的研究'],['法语 métrologie → 英语 metrology','测量科学及其应用']],'校准一台秤不只是把数字调好看，而是建立它与可靠标准的联系。计量学也研究单位、测量方法和结果的可比较性，不只关心仪器显示多少位。','industrial metrology；a metrology laboratory；measurement standards in metrology。','meteorology 多了 meteor-，研究大气天气；metrology 研究测量，名称相近但对象不同。',('The metrology laboratory calibrated the balance against a reference standard.','计量实验室依据参考标准校准了天平。'),('Reliable manufacturing depends on metrology as well as good machinery.','可靠的制造既依赖良好的机器，也依赖计量工作。'),sources=['https://www.merriam-webster.com/dictionary/metrology','https://en.wiktionary.org/wiki/metrology#English','https://www.bipm.org/en/technical-areas','https://www.bipm.org/en/web/guest/publications/guides']),
E('rheology','英 /riːˈɒlədʒi/；美 /riˈɑːlədʒi/','流变学','看看材料受力以后怎样流动、拉长、变形，以及松手后怎样变化。','希腊 rhéō“流动” + -logy，是二十世纪的学术造词；流变学会历史记录把 Bingham 提出名称的时间列为 1928 年。',L+[['希腊 rhéō〔流动〕→ rheo- + -logy','用流动的形象命名材料变形研究'],['现代英语 rheology','材料流动与变形的科学；不只研究普通液体']],'蜂蜜慢慢流、面团拉开后回缩、膏体被挤出，表现出不同的流动与变形方式。材料看起来像固体，也可能在较长时间或特定受力下显出流动。','the rheology of a polymer；a rheology test；research in rheology。','viscosity 是描述流动阻力的一类性质；rheology 是研究变形与流动的整个领域。',('The researchers tested the rheology of the dough before baking.','研究者在烘焙前测试了面团的流变性质。'),('The paint’s rheology affects how smoothly it spreads under a brush.','涂料的流变性质会影响它在刷子下铺展得是否顺滑。'),sources=['https://www.societyofrheology.org/history','https://www.societyofrheology.org/','https://en.wiktionary.org/wiki/rheology#English'])
])
PSY=L+[['希腊 psykhḗ〔灵魂、心灵〕+ -logia → 文艺复兴时期拉丁 psychologia','以心灵为对象的学术名称'],['法语 psychologie → 英语 psychology','后来成为研究心理与行为的现代学科']]
PHY=L+[['希腊 phúsis〔自然〕+ -logía → physiología → 拉丁 physiologia','早期指关于自然的论述'],['法语 physiologie → 英语 physiology','后来专指生物功能与生命机制的研究']]
PATH=L+[['希腊 páthos〔遭受、苦痛、疾病〕+ -logie → 法语 pathologie','形成研究疾病的学科名称'],['英语 pathology','病理学；疾病的性质与变化过程']]
NEU=L+[['希腊 neûron〔筋、神经〕+ -logia → 新拉丁 neurologia','形成神经系统研究的学术名称'],['英语 neurology','神经学；现代常指神经内科相关专科']]
W.extend([
E('psychology','英 /saɪˈkɒlədʒi/；美 /saɪˈkɑːlədʒi/','心理学；心理特点','研究人怎样感知、记住、思考、感受和行动。','psycho- 接希腊 psykhḗ“心灵”，加 -logy；经近代拉丁 psychologia、法语 psychologie 进入英语。词首 p 不发音。',PSY,'它不是看一眼就猜出别人想什么，而是用观察、实验等方法研究心理和行为。the psychology of a group 也可泛指这个群体的心理特点，不一定在命名一门新学科。','cognitive psychology；social psychology；the psychology of decision-making。','psychology 是研究领域；mind reading 是读心说法，不能把学科知识等同于准确猜心。',('She studies psychology to understand how people make decisions.','她学习心理学，希望理解人们怎样作决定。'),('The experiment tested a theory from cognitive psychology.','这个实验检验了认知心理学中的一个理论。'),sources=['https://en.wiktionary.org/wiki/psychology#English','https://www.buckingham.ac.uk/psychology/why/']),
E('psychological','英 /ˌsaɪkəˈlɒdʒɪkəl/；美 /ˌsaɪkəˈlɑːdʒɪkəl/','心理的；心理学的','把注意力放到想法、感受和心理过程这一面。','英语 psychology + -ical；延续词首不发音的 p，重音移至 -log-。',PSY+[['英语 psychology + -ical → psychological','与心理或心理学有关的']],'psychological pressure 是心理压力，psychological research 是心理学研究。说一个因素是 psychological，不意味着它是装出来的，也不意味着不会影响身体。','psychological support；psychological factors；psychological research。','physiological 着重身体功能；psychological 着重心理过程，两方面会相互影响。',('The move had a significant psychological effect on the children.','这次搬家对孩子们产生了明显的心理影响。'),('The study examines psychological factors that influence attention.','研究分析影响注意力的心理因素。')),
E('psychologist','英 /saɪˈkɒlədʒɪst/；美 /saɪˈkɑːlədʒɪst/','心理学家；心理学专业人员','用心理学知识做研究、评估或专业服务的人。','英语 psychology + -ist；词尾表示从事这类工作的人。',PSY+[['英语 psychology + -ist → psychologist','心理学研究或专业实践人员']],'有的研究记忆，有的帮助学校或组织，有的从事临床心理工作。并非所有 psychologist 都做心理治疗，名称本身也不等同于医学专科医生。','a clinical psychologist；an educational psychologist；a research psychologist。','psychiatrist 是精神科医生；psychologist 的培训与工作路径不同，不能只按中文“心理医生”混用。',('The psychologist designed a task to measure attention.','心理学家设计了一个测量注意力的任务。'),('An educational psychologist helped the school understand the child’s learning needs.','一位教育心理学专业人员帮助学校了解这个孩子的学习需要。'),sources=['https://en.wiktionary.org/wiki/psychologist#English','https://www.northumbria.ac.uk/study-at-northumbria/courses/msc-psychology-distance-learning-dtdppy6/archive/what-is-psychology-blog-org/']),
E('neuropsychology','英 /ˌnjʊərəʊsaɪˈkɒlədʒi/；美 /ˌnʊroʊsaɪˈkɑːlədʒi/','神经心理学','把脑的工作与记忆、语言、注意力等心理能力连起来研究。','neuro- “神经” + psychology；不是把两个领域简单并排列出，而是聚焦它们之间的关系。',PSY+[['英语 neuro- + psychology → neuropsychology','研究脑与心理功能、行为的关系']],'例如脑损伤后某种记忆受影响，而另一种能力保留，能帮助研究者理解心理功能怎样组织。临床工作还包括评估这些变化对日常生活的影响。','clinical neuropsychology；a neuropsychology assessment；research in neuropsychology。','neurobiology 更侧重神经系统的生物机制；neuropsychology 更直接连接心理功能与行为。',('The neuropsychology assessment included tasks involving memory and language.','神经心理评估包含记忆和语言方面的任务。'),('Her research in neuropsychology explores how brain injury affects planning.','她的神经心理学研究探讨脑损伤怎样影响计划能力。'),sources=['https://en.wiktionary.org/wiki/neuropsychology#English','https://www.bristol.ac.uk/psychology-neuroscience/postgraduate-taught-programmes/neuropsychology/']),
E('physiology','英 /ˌfɪziˈɒlədʒi/；美 /ˌfɪziˈɑːlədʒi/','生理学；生理功能','把活的身体想成正在运行的系统：它怎样呼吸、供能、传信和调节。','希腊 phúsis“自然” + -logia，早期是自然论述，经拉丁、法语进入英语后逐渐集中于生命功能。',PHY,'看见心脏有几个腔室，是结构问题；追问它怎样调节心跳和泵血，就进入生理问题。生理学也研究植物、细胞等，并不只属于人的身体。','human physiology；plant physiology；the physiology of exercise。','anatomy 着重身体怎样构成；physiology 着重这些部分怎样工作，两者相互支撑。',('The physiology lesson explains how the body regulates temperature.','生理学课解释了身体怎样调节体温。'),('She studies plant physiology, especially how leaves respond to drought.','她研究植物生理学，尤其关注叶片如何应对干旱。'),sources=['https://en.wiktionary.org/wiki/physiology#English','https://www.physoc.org/explore-physiology/what-is-physiology/']),
E('physiological','英 /ˌfɪziəˈlɒdʒɪkəl/；美 /ˌfɪziəˈlɑːdʒɪkəl/','生理的；与生命功能有关的','关注身体怎样反应、调节和运作。','现代可按 physiology + -ical 理解；另有拉丁 physiologicus + -al 的来源分析，与 physio- + -logical 的分析并行。',[['希腊 physiología／physiologikós → 拉丁 physiologia／physiologicus','关于自然及其功能的学术形式'],['英语 physiological','可分析为拉丁形容词加 -al；现代与 physiology + -ical 对应']],'运动后心率变化可以是 physiological response。生理过程有正常调节，也可能受疾病改变；不能看到 physiological 就默认“没有问题”。','a physiological response；physiological changes；physiological processes。','physical 可以宽泛地指身体或物理性质；physiological 更集中于生命功能与机制。',('The study recorded physiological responses to exercise.','研究记录了运动引起的生理反应。'),('The plants showed physiological changes after several days without water.','这些植物缺水几天后出现了生理变化。'),sources=['https://en.wiktionary.org/wiki/physiological#English','https://www.physoc.org/explore-physiology/what-is-physiology/']),
E('pathology','英 /pəˈθɒlədʒi/；美 /pəˈθɑːlədʒi/','病理学；病理变化','研究疾病是什么、怎样发生，以及组织和功能哪里发生了改变。','借法语 pathologie，由希腊 páthos“疾病、遭受”与 -logie 组成；不是英语 path“道路”的派生。',PATH,'病理工作可以分析组织、细胞或其他实验室材料，帮助弄清疾病。the pathology of a condition 则可指这个病本身的变化机制，不只是医院里一个科室的名称。','a pathology report；the pathology of a disease；clinical pathology。','symptom 是人感受到或表现出的症状；pathology 着重疾病及其变化，不能仅凭一个症状替代病理分析。',('The doctor reviewed the pathology report with the patient.','医生和患者一起查看了病理报告。'),('The lecture explains the pathology of the disease at the cellular level.','讲座从细胞层面解释了这种病的病理变化。'),sources=['https://en.wiktionary.org/wiki/pathology#English','https://www.rcpath.org/discover-pathology/what-is-pathology.html']),
E('pathological','英 /ˌpæθəˈlɒdʒɪkəl/；美 /ˌpæθəˈlɑːdʒɪkəl/','病理的；病态的；异常到失控的〔引申〕','医学里指与疾病变化有关；日常引申可以说一种行为异常强烈、反复出现。','英语 pathology + -ical；名词首部弱读 /pə-/ 在这里常变为 /pæθ-/。',PATH+[['英语 pathology + -ical → pathological','病理相关的 → 也可引申为病态、极端异常的']],'pathological changes 是病理变化。小说里的 a pathological liar 常形容习惯性、失控地撒谎的人，未必是在提供正式诊断；不能见到夸张用语就当医学结论。','pathological changes；pathological tissue；a pathological liar。','pathological 有明确医学用途，也有日常贬义引申；unusual 只是不同寻常，力度更弱。',('The sample showed no obvious pathological changes.','样本未显示明显的病理变化。'),('The novel portrays him as a pathological liar who rewrites every event.','小说把他写成一个病态的撒谎者，连每件事的经过都要改写。')),
E('neurology','英 /njʊəˈrɒlədʒi/；美 /nʊˈrɑːlədʒi/','神经学；神经内科','围绕脑、脊髓和神经，研究并诊治它们的功能问题。','借新拉丁 neurologia，neuro- “神经” + -logia；这里的神经不是日常“紧张兮兮”的性格评价。',NEU,'医院里的 neurology department 关注神经系统疾病。这个系统负责运动、感觉和许多其他功能，所以专科范围不只限于“头部问题”。','a neurology clinic；the neurology department；clinical neurology。','neurosurgery 强调神经外科手术；neurology 是另一专科方向，两者会合作。',('The hospital opened a new outpatient clinic for neurology.','医院开设了一个新的神经内科门诊。'),('Her training in neurology included disorders affecting movement and sensation.','她的神经内科培训包括影响运动和感觉的疾病。'),sources=['https://en.wiktionary.org/wiki/neurology#English']),
E('neurological','英 /ˌnjʊərəˈlɒdʒɪkəl/；美 /ˌnʊrəˈlɑːdʒɪkəl/','神经系统的；神经学的','说明问题或检查涉及脑、脊髓和神经的功能。','英语 neurology + -ical，构成相应形容词；主重音移到 -log-。',NEU+[['英语 neurology + -ical → neurological','关于神经系统及其疾病、检查的']],'a neurological examination 可以检查反射、感觉和动作。这个形容词标出系统范围，不是把某种情绪直接诊断为神经疾病。','a neurological examination；neurological symptoms；a neurological condition。','nervous 可指神经相关，也常指紧张；neurological 明确指神经系统或神经学。',('The clinician carried out a neurological examination.','临床医生进行了神经系统检查。'),('The study follows changes in neurological function over time.','研究持续追踪神经功能的变化。')),
E('epidemiology','英 /ˌepɪdiːmiˈɒlədʒi/；美 /ˌepɪdiːmiˈɑːlədʒi/','流行病学','把镜头从一个人拉到一群人：什么人、什么地方、什么时候更常出现某种健康问题？','希腊 epi- “在……之中” + dêmos“人群”形成流行于人群的词族，经后期拉丁 epidemia，再与 -logy 组成学科名。',[['希腊 dêmos 与另一支 lógos','民众；话语、说明——两条组合材料'],['希腊 epídēmos／epidēmía → 后期拉丁 epidemia','在人群中发生、流行的状况'],['epidemia + -logy → 英语 epidemiology','研究人群中健康事件的分布、相关因素及预防控制']],'比较不同群体的发病情况、查找可能的影响因素，是核心工作。它也研究慢性病、伤害等，并不只在传染病暴发时才有用。','cancer epidemiology；an epidemiology study；the epidemiology of a disease。','clinical medicine 常着眼个体诊疗；epidemiology 着眼人群规律，二者提供不同层面的证据。',('The epidemiology team compared illness rates across several neighbourhoods.','流行病学团队比较了几个街区的患病率。'),('Her research in epidemiology examines long-term patterns of heart disease.','她的流行病学研究分析心脏病的长期分布规律。'),sources=['https://en.wiktionary.org/wiki/epidemiology#English','https://www.cdc.gov/reproductive-health/glossary/']),
E('radiology','英 /ˌreɪdiˈɒlədʒi/；美 /ˌreɪdiˈɑːlədʒi/','放射学；医学影像相关专科','借助影像看身体内部，并把影像用于诊断或引导治疗。','radio- 在这里接拉丁 radius“射线”，加 -logy；名称与早期射线应用有关，现代范围已扩大。',L+[['拉丁 radius〔光线、射线〕→ radio- + -logy','以射线研究和应用命名的近代词'],['英语 radiology','医学影像专科，现代也使用超声、磁共振等技术']],'虽然名称中有“放射”，科室也会使用不依赖电离辐射的超声和 MRI。不能因此把所有 radiology 检查都理解成照 X 光。','a radiology department；diagnostic radiology；interventional radiology。','radiography 较具体地指影像获取，常见于 X 光成像；radiology 是更广的专业领域。',('The images were sent to the radiology department for review.','这些影像被送到放射科审阅。'),('The radiology service offers both ultrasound and MRI examinations.','放射科提供超声和磁共振检查。'),sources=['https://en.wiktionary.org/wiki/radiology#English','https://www.radiologyinfo.org/en/info/professions-diagnostic-radiology']),
E('phrenology','英 /frɪˈnɒlədʒi/；美 /frəˈnɑːlədʒi/','颅相学〔已被否定的旧学说〕','过去有人摸头骨的凸凹，就声称能判断性格和能力；这个词指那套学说。','phreno- 接希腊 phrḗn“膈膜；心智”，加 -logy；古人曾把身体内部器官与思想、感情联系起来。',L+[['希腊 phrḗn〔膈膜；心智〕→ phreno- + -logy','以心智研究命名'],['十九世纪英语 phrenology','主张通过头骨外形判断心理能力的学说，后来被否定']],'学习这个词，重点是认识科学史上的一种错误方法。头骨图上画满性格区域，并不能使那些判断变成可靠的心理测量。','the history of phrenology；a phrenology chart；belief in phrenology。','neuroscience 研究神经系统；phrenology 不是现代脑科学的另一种称呼。',('The museum displayed a phrenology chart as part of the history of medicine.','博物馆把一张颅相学图表作为医学史展品陈列。'),('The lecture explained why phrenology cannot reliably reveal a person’s character.','讲座解释了颅相学为何不能可靠地揭示一个人的性格。'),sources=['https://www.etymonline.com/word/phrenology','https://en.wiktionary.org/wiki/phrenology#English']),
E('parapsychology','英 /ˌpærəsaɪˈkɒlədʒi/；美 /ˌpærəsaɪˈkɑːlədʒi/','超心理学','研究被声称超出通常心理与物理解释的现象，例如心灵感应。','para- 在这里表示超出、在常规之外，加 psychology；不是把“辅助心理学”当作普通课程名称。',PSY+[['英语 para- + psychology → parapsychology','对所谓超常心理现象的研究']],'这里要保留“声称”二字：有这个研究名称，不表示心灵感应等已经被可靠证实。讨论通常涉及实验能否排除巧合、信息泄露，以及结果能否重复。','research in parapsychology；claims in parapsychology；a history of parapsychology。','psychology 是现代心理学的大领域；parapsychology 的特定主张存在重大证据和重复验证问题。',('The seminar on parapsychology discussed how to rule out ordinary explanations.','超心理学研讨课讨论了怎样排除普通解释。'),('The historian examined the role of early laboratories in parapsychology.','历史学家研究了早期实验室在超心理学中的作用。'),sources=['https://dictionary.apa.org/parapsychology','https://en.wiktionary.org/wiki/parapsychology#English']),
E('logotherapy','英 /ˌlɒɡəˈθerəpi/；美 /ˌlɑːɡəˈθerəpi/，亦 /ˌlɔːɡə-/','意义疗法','围绕“什么对这个人的生活有意义”展开的一种心理治疗取向。','logo- 在 Frankl 的术语中取希腊 lógos“意义”，加 therapy“治疗”；不是“讲道理就能治好”的直译。',L+[['希腊 lógos〔这里取意义〕+ 治疗成分 → 德语 Logotherapie','Frankl 在二十世纪发展并命名的治疗取向'],['英语 logotherapy','以寻找个人生活意义为核心的心理治疗取向']],'它关注个人在具体处境中认为什么值得投入，不是由治疗者统一发给每个人一份“人生意义”。读到这个术语时，应把它认作一种特定理论传统，而不是所有谈话治疗。','Frankl’s logotherapy；an introduction to logotherapy；a discussion of logotherapy。','speech therapy 帮助言语、语言等功能；logotherapy 在这里关注意义，两者虽然都含话语相关词根，却不是同一种服务。',('The book introduces logotherapy through questions about purpose and responsibility.','这本书通过目的与责任的问题介绍意义疗法。'),('The seminar compared Frankl’s logotherapy with other approaches to psychotherapy.','研讨课比较了 Frankl 的意义疗法和其他心理治疗取向。'),sources=['https://www.viktorfrankl.org/logotherapy.html','https://www.merriam-webster.com/medical/logotherapy','https://en.wiktionary.org/wiki/logotherapy#English']),
E('cryptology','英 /krɪpˈtɒlədʒi/；美 /krɪpˈtɑːlədʒi/','密码学〔广义，含设计与分析〕','既研究怎样把信息保护起来，也研究这种保护能不能被分析突破。','希腊 kryptós“隐藏的” + -logia，近代拉丁 cryptologia 等形式进入英语；crypto- 在这里不是专指加密货币。',L+[['希腊 kryptós〔隐藏〕+ -logia → 近代拉丁 cryptologia','围绕隐秘信息的学术构词'],['英语 cryptology','密码设计与密码分析的综合领域']],'设计一个密码系统属于 cryptography；研究它的安全性和可能的破解方法属于 cryptanalysis。cryptology 常把这两面合起来说。','the history of cryptology；modern cryptology；a course in cryptology。','cryptocurrency 是加密货币；cryptology 是更广且历史更早的密码研究领域。',('The museum traces the history of cryptology from handwritten ciphers to digital systems.','博物馆追溯了密码学从手写密码到数字系统的历史。'),('The course in cryptology covers both designing ciphers and analysing their weaknesses.','密码学课程既讲密码设计，也讲弱点分析。'),sources=['https://en.wiktionary.org/wiki/cryptology#English','https://www.nsa.gov/about/faqs/'])
])
TOX=L+[['希腊 toxikón〔毒，原联系箭毒〕→ toxico- + -logie → 法语 toxicologie','从毒物概念形成近代研究名称'],['英语 toxicology','研究物质等因素如何对生物造成有害影响']]
HEM=L+[['希腊 haîma／haímat-〔血〕→ 新拉丁科学构词 haemato- / hemato-','血液相关的构词成分'],['haemato- / hemato- + -logy → haematology / hematology','血液及相关疾病研究；两种英语拼写']]
W.extend([
E('pharmacology','英 /ˌfɑːməˈkɒlədʒi/；美 /ˌfɑːrməˈkɑːlədʒi/','药理学','追问药进入身体以后做了什么，身体又怎样处理它。','pharmaco- 来自希腊 phármakon“药物、毒物”，加 -logy；现代学科名用古典材料组成。',L+[['希腊 phármakon〔药物、毒物〕→ pharmaco- + -logy','将药物作用作为研究对象'],['英语 pharmacology','药物与生物系统相互作用的研究']],'它研究药与受体怎样结合，也研究吸收、分布和代谢等过程。名字不只是“药品清单学”，更关心药为什么产生某种作用。','clinical pharmacology；a course in pharmacology；the pharmacology of a drug。','pharmacy 涉及药学及药品调配、供应等实践；pharmacology 集中研究药物作用机制。',('The pharmacology lecture explains how the drug interacts with its receptor.','药理学讲座解释了这种药怎样与受体相互作用。'),('She studied pharmacology before joining a drug research team.','她先学习药理学，后来加入药物研究团队。'),sources=['https://en.wiktionary.org/wiki/pharmacology#English','https://www.bps.ac.uk/careers-education/what-is-pharmacology/']),
E('toxicology','英 /ˌtɒksɪˈkɒlədʒi/；美 /ˌtɑːksɪˈkɑːlədʒi/','毒理学','不只问“有没有毒”，还问什么剂量、怎样接触、接触多久会造成什么影响。','借法语 toxicologie，toxico- “毒” + -logie；toxikón 的希腊历史联系涂在箭上的毒物。',TOX,'同一种物质的影响会随接触条件改变，所以毒理学需要实验数据和情境。它既用于药物研发，也用于环境和职业健康研究，不只分析犯罪中的毒药。','environmental toxicology；a toxicology report；toxicology testing。','toxicity 是毒性这一性质或程度；toxicology 是研究有害作用的学科。',('The toxicology study compared the effects of different exposure levels.','毒理学研究比较了不同接触水平产生的影响。'),('The laboratory prepared a toxicology report on the samples.','实验室为这些样本出具了毒理学报告。'),sources=['https://en.wiktionary.org/wiki/toxicology#English','https://www.niehs.nih.gov/health/topics/science/toxicology']),
E('toxicological','英 /ˌtɒksɪkəˈlɒdʒɪkəl/；美 /ˌtɑːksɪkəˈlɑːdʒɪkəl/','毒理学的；涉及有害作用评估的','说明这组数据或测试是在考察物质怎样造成伤害。','英语 toxicology + -ical；不是 toxic“有毒的”的简单同义词。',TOX+[['英语 toxicology + -ical → toxicological','与毒理学研究或评估有关的']],'toxicological data 可以显示某种条件下没有观察到某项有害影响，也可以显示风险。这个形容词只标研究方向，不预先宣布结论。','toxicological data；a toxicological assessment；toxicological testing。','toxic 表示有毒或有害；toxicological 表示毒理学相关，测试本身不是“有毒”。',('The review considered both the chemical and toxicological data.','评审同时考虑了化学数据和毒理学数据。'),('Further toxicological testing was required before the team could interpret the result.','团队还需要进一步的毒理学测试，才能解释这个结果。'),sources=['https://en.wiktionary.org/wiki/toxicological#English','https://www.niehs.nih.gov/health/topics/science/toxicology']),
E('toxicologist','英 /ˌtɒksɪˈkɒlədʒɪst/；美 /ˌtɑːksɪˈkɑːlədʒɪst/','毒理学家；毒理学专业人员','把接触条件与生物反应联系起来，评估有害作用的人。','英语 toxicology + -ist；研究者名称由学科名形成。',TOX+[['英语 toxicology + -ist → toxicologist','研究有害作用及其风险的专业人员']],'他会问样本怎么取、剂量怎么算、实验结果能适用到什么范围。并不是只要在样本中检出一个化学名称，就能宣布它造成了全部问题。','an environmental toxicologist；a forensic toxicologist；consult a toxicologist。','chemist 研究化学的范围很广；toxicologist 特别关注有害生物作用，也会用到化学知识。',('The toxicologist asked how long the workers had been exposed.','毒理学专业人员询问了工人接触该物质的时长。'),('A toxicologist reviewed the study’s dose measurements.','一位毒理学家审查了研究中的剂量测量。'),sources=['https://en.wiktionary.org/wiki/toxicologist#English','https://www.oxfordlearnersdictionaries.com/definition/english/toxicologist','https://www.toxicology.org/careers/toxicologist/becomeTox.asp']),
E('cardiology','英 /ˌkɑːdiˈɒlədʒi/；美 /ˌkɑːrdiˈɑːlədʒi/','心脏病学；心脏内科','围绕心脏怎样工作，以及它出现什么问题展开的医学领域。','cardio- 来自希腊 kardía“心脏”，加 -logy；这是研究器官的术语，card- 不是卡片。',L+[['希腊 kardía〔心脏〕→ cardio- + -logy','以心脏为对象的医学构词'],['英语 cardiology','心脏及相关疾病的研究与临床专科']],'心律、心脏泵血和相关血管问题都可能进入这个领域。并不是所有 cardiology 工作都是开胸手术，心脏外科有自己的专科名称。','a cardiology clinic；the cardiology department；training in cardiology。','cardiac surgery 强调心脏手术；cardiology 是研究和诊治心脏疾病的专科领域。',('She completed a placement in the cardiology department.','她在心脏内科完成了一段实习。'),('The cardiology team reviewed the patient’s heart recordings.','心脏科团队审阅了患者的心脏检查记录。'),sources=['https://en.wiktionary.org/wiki/cardiology#English']),
E('dermatology','英 /ˌdɜːməˈtɒlədʒi/；美 /ˌdɜːrməˈtɑːlədʒi/','皮肤病学；皮肤科','以皮肤为中心，也关心毛发和指甲的健康问题。','dermato- 接希腊 dérma、词干 dermat- “皮肤”，加 -logy；中间的 t 来自原有词干，不是随意添的。',L+[['希腊 dérma／dermat-〔皮肤〕→ dermato- + -logy','以皮肤及相关组织为对象的医学构词'],['英语 dermatology','皮肤、毛发与指甲相关的医学专科']],'皮疹、皮肤病变、一些毛发和指甲问题都在范围内。它不只是美容服务的学术名称，许多工作涉及疾病诊断和长期管理。','a dermatology clinic；clinical dermatology；a referral to dermatology。','cosmetics 主要说美容用品或修饰；dermatology 是医学领域，虽可有美容相关分支但范围远不止此。',('The dermatology clinic sees patients with skin and nail conditions.','皮肤科门诊接诊有皮肤和指甲问题的患者。'),('The medical student spent a month studying dermatology.','这名医学生用一个月学习皮肤病学。'),sources=['https://en.wiktionary.org/wiki/dermatology#English','https://www.aad.org/public/fad/what-is-a-derm']),
E('ophthalmology','英 /ˌɒfθælˈmɒlədʒi/；美 /ˌɑːfθəlˈmɑːlədʒi/；亦有 /pθ/ 读法','眼科学；眼科','研究眼睛本身的结构、功能和疾病，并包括相应的医疗与手术。','ophthalmo- 来自希腊 ophthalmós“眼”，加 -logy；长拼写可以按 ophthalmo + logy 分块认。',[['希腊 ophthalmós〔眼〕与 lógos〔论述〕','分别贡献研究对象与学科后缀的词源'],['近代 ophthalmo- + -logy','以眼睛为对象的医学构词'],['英语 ophthalmology','眼科学及眼科医疗专科']],'它不仅检查看得清不清，还处理视网膜、晶状体等结构的疾病。拼写中的 ph 常读 /f/，th 读 /θ/，不必把每个字母都独立念出来。','an ophthalmology clinic；paediatric ophthalmology；training in ophthalmology。','optometry 与视力检查、视觉保健等密切相关；ophthalmology 是眼科医学专科，包含眼部疾病医疗与手术。',('The ophthalmology team examined the patient’s retina.','眼科团队检查了患者的视网膜。'),('She chose ophthalmology because she wanted to combine medical care with eye surgery.','她选择眼科学，因为希望兼做眼科诊疗和眼部手术。'),sources=['https://en.wiktionary.org/wiki/ophthalmology#English','https://aao.org/eye-health/tips-prevention/ophthalmology-training-certification']),
E('urology','英 /jʊəˈrɒlədʒi/；美 /jʊˈrɑːlədʒi/','泌尿学；泌尿外科','围绕尿从哪里形成、怎样排出，以及相关器官出现什么问题的医学领域。','uro- 来自希腊 oûron“尿”，加 -logy；现代专科范围比字面“尿的研究”更广。',L+[['希腊 oûron〔尿〕→ uro- + -logy','以泌尿功能命名的医学术语'],['英语 urology','泌尿系统及男性生殖系统相关的专科']],'肾脏、输尿管、膀胱、尿道都与这个领域有关；也包括男性生殖系统问题。虽然中文常叫泌尿外科，工作并不全部是手术。','a urology clinic；the urology department；paediatric urology。','nephrology 更专注肾脏功能与肾病的内科方向；urology 覆盖更广的泌尿系统及相关外科问题。',('The hospital’s urology department treats patients of different ages.','医院的泌尿科接诊不同年龄的患者。'),('The student observed how the urology team investigated bladder problems.','学生观摩了泌尿科团队怎样检查膀胱问题。'),sources=['https://en.wiktionary.org/wiki/urology#English','https://www.urologyhealth.org/urology-a-z/what-is-urology']),
E('virology','英 /vaɪˈrɒlədʒi/；美 /vaɪˈrɑːlədʒi/','病毒学','研究病毒怎样复制、变化，并与宿主相互作用。','viro- 来自拉丁 vīrus“毒液、毒”，在现代科学中指病毒，加 -logy；古人的 virus 概念不等于今天已知的病毒颗粒。',[['拉丁 vīrus〔毒液〕→ 现代科学 virus〔病毒〕；另一路希腊 lógos', '拉丁来源的研究对象与希腊来源的学科后缀在近代结合'], ['英语 viro- + -logy → virology', '研究病毒及其与宿主关系的学科']],'病毒依赖宿主细胞完成复制，因此研究者不仅看病毒，也看感染细胞怎样改变。这个领域不只研究人的病，也研究植物、动物和其他宿主的病毒。','a virology laboratory；molecular virology；research in virology。','bacteriology 研究细菌；virology 研究病毒，不能把二者都当成同一类“细菌”。',('The virology laboratory compared the genetic sequences of several samples.','病毒学实验室比较了几个样本的遗传序列。'),('Her research in virology focuses on viruses that infect plants.','她的病毒学研究聚焦于感染植物的病毒。'),sources=['https://en.wiktionary.org/wiki/virology#English']),
E('hematology','英 /ˌhiːməˈtɒlədʒi/；美 /ˌhiːməˈtɑːlədʒi/','血液学；血液科〔美式常见拼写〕','研究血液怎样组成、形成和工作，以及它出现哪些疾病。','hemato- 来自希腊 haîma、词干 haímat- “血”，加 -logy；与 haematology 是同一词的拼写变体。',[['希腊 haîma／haímat-〔血〕与 lógos〔论述〕', '两种希腊材料分别提供研究对象与学科后缀'], ['近代科学构词 haemato-／hemato- + -logy', '血液成分与研究后缀结合'], ['haemato- / hemato- + -logy → haematology / hematology', '血液及相关疾病研究；两种英语拼写']],'它包括红细胞、白细胞、血小板、凝血以及造血相关问题。血液学并不是“做一次普通血检”的同义词，而是围绕这些问题的整个领域。','a hematology laboratory；the hematology department；clinical hematology。','hematology 研究血液；cardiology 研究心脏，虽然都与循环有关，但关注对象不同。',('The hematology laboratory examined the blood cells under a microscope.','血液学实验室在显微镜下检查了血细胞。'),('She joined the hematology team studying disorders of blood clotting.','她加入了研究凝血障碍的血液学团队。'),sources=['https://en.wiktionary.org/wiki/hematology#English','https://www.hematology.org/education/patients']),
E('haematology','英 /ˌhiːməˈtɒlədʒi/；美 /ˌhiːməˈtɑːlədʒi/','血液学；血液科〔英式常见拼写〕','与 hematology 研究同一套血液问题，只保留了较传统的 ae 拼写。','haemato- “血” + -logy；ae 反映希腊 ai 经拉丁转写的传统，现代读音并不因此多出一个音节。',[['希腊 haîma／haímat-〔血〕与 lógos〔论述〕', '两种希腊材料分别提供研究对象与学科后缀'], ['近代科学构词 haemato-／hemato- + -logy', '血液成分与研究后缀结合'], ['haemato- / hemato- + -logy → haematology / hematology', '血液及相关疾病研究；两种英语拼写'], ['英式常见形式 haematology', '与美式常见形式 hematology 并行，不是两个专科']],'英国医院的 Haematology 标牌和美国资料中的 Hematology 指同一专业。检索资料时认识两种拼写，能避免误以为搜到了不同学科。','a haematology ward；a haematology report；clinical haematology。','haematology 与 hematology 是地区拼写习惯差异，不能靠 ae 判断疾病种类。',('The sample was delivered to the haematology laboratory before noon.','样本在中午之前送到了血液学实验室。'),('The appointment letter listed the haematology clinic on the second floor.','预约信写明血液科门诊在二楼。'),sources=['https://en.wiktionary.org/wiki/haematology#English']),
E('histology','英 /hɪˈstɒlədʒi/；美 /hɪˈstɑːlədʒi/','组织学','把组织切得很薄，在显微镜下看细胞怎样排成层、管或其他结构。','histo- 来自希腊 histós“织物、织成的东西”，在生物学中转用为组织，加 -logy。',[['希腊 histós〔织物〕与 lógos〔论述〕', '两种独立材料：组织结构的比喻，与学科后缀的来源'], ['近代科学构词 histo-〔组织〕', '把身体组织想成由成分有序构成的结构'], ['英语 histo- + -logy → histology', '组织的显微结构研究']],'肠壁、皮肤、肌肉含有不同的组织结构，组织学帮助辨认它们。名字里的“组织”是身体组织，不是公司或社会组织。','a histology slide；a histology laboratory；normal histology。','cytology 更聚焦细胞；histology 更看细胞在组织中怎样排列及其周围结构。',('The histology class compared sections of skin and muscle.','组织学课比较了皮肤和肌肉的切片。'),('The tissue was prepared for examination in the histology laboratory.','组织样本经处理后，将在组织学实验室接受检查。'),sources=['https://en.wiktionary.org/wiki/histology#English']),
E('cytology','英 /saɪˈtɒlədʒi/；美 /saɪˈtɑːlədʒi/','细胞学；细胞学检查','把细胞作为观察单位，研究它的形态、结构和变化。','cyto- 来自希腊 kýtos“中空容器”，科学中转用为细胞，再加 -logy；不是 city“城市”。',[['希腊 kýtos〔中空容器〕与 lógos〔论述〕', '两种独立材料：小腔室的形象，与学科后缀的来源'], ['近代科学构词 cyto-〔细胞〕', '中空容器的旧意象用于细胞相关名称'], ['英语 cyto- + -logy → cytology', '细胞研究；临床也指细胞样本检查']],'临床中可以观察脱落或采集到的细胞，而不总需要一整块组织。学科义则更广，不只等于某一项筛查。','a cytology sample；a cytology report；diagnostic cytology。','histology 通常更看组织结构；cytology 更看细胞本身，两种检查能提供不同层面的信息。',('The laboratory prepared the fluid sample for cytology.','实验室处理了液体样本，以便进行细胞学检查。'),('The cytology report described the appearance of the cells.','细胞学报告描述了细胞的外观。'),sources=['https://en.wiktionary.org/wiki/cytology#English']),
E('nephrology','英 /nəˈfrɒlədʒi/；美 /nəˈfrɑːlədʒi/','肾脏病学；肾内科','重点看肾脏怎样维持身体内部的平衡，以及肾功能出了什么问题。','nephro- 来自希腊 nephrós“肾”，加 -logy，构成现代医学学科名。',[['希腊 nephrós〔肾〕与 -logía〔论述、研究〕','两份词源材料并列'],['近代 nephro- + -logy','以肾脏为对象的医学构词'],['英语 nephrology','肾脏疾病与肾功能的研究、诊治领域']],'肾不只“造尿”，还参与水、电解质等调节。肾内科的重点是这些功能及其疾病；与泌尿系统外科问题有合作，也有各自侧重。','a nephrology clinic；clinical nephrology；a nephrology referral。','urology 涵盖泌尿系统和相关外科范围；nephrology 更集中于肾病及肾功能管理。',('The nephrology team reviewed changes in kidney function over several months.','肾内科团队查看了几个月来肾功能的变化。'),('Her medical placement in nephrology included visits to the dialysis unit.','她在肾内科实习期间也去透析科室学习。'),sources=['https://en.wiktionary.org/wiki/nephrology#English','https://www.kidney.org/sites/default/files/kidney_transplant.pdf']),
E('bacteriology','英 /bækˌtɪəriˈɒlədʒi/；美 /bækˌtɪriˈɑːlədʒi/','细菌学','专门研究细菌怎样生长、起作用，以及怎样与其他生物相处。','bacterio- 来自新拉丁 bacterium，接希腊 baktḗrion“小棒”，再加 -logy；名字保留早期观察某些杆状细菌的形象。',[['希腊 baktḗrion〔小棒〕→ 新拉丁 bacterium〔细菌〕；另一路 lógos', '细菌名称与研究后缀分别提供构词材料'], ['英语 bacterio- + -logy → bacteriology', '细菌的研究']],'细菌有许多形状，不能因名称来自小棒，就说所有细菌都是杆状。细菌学既研究病原菌，也研究发酵和环境中的细菌。','a bacteriology laboratory；food bacteriology；research in bacteriology。','virology 研究病毒；bacteriology 研究细菌，microbiology 则覆盖更大的微观生命领域。',('The bacteriology team identified the organisms growing in the culture.','细菌学团队鉴定了培养物中生长的微生物。'),('The course in bacteriology includes bacteria used in food production.','细菌学课程也讲用于食品生产的细菌。'),sources=['https://en.wiktionary.org/wiki/bacteriology#English']),
E('otolaryngology','英 /ˌəʊtəʊˌlærɪŋˈɡɒlədʒi/；美 /ˌoʊtoʊˌlerɪŋˈɡɑːlədʒi/','耳鼻喉科学；耳鼻喉科','把耳、鼻、咽喉及相关头颈部问题放在一个相连的专科里处理。','oto- “耳” + laryngo- “喉” + -logy；这一个较短词形没写出鼻的 rhino-，实际专业范围仍包括鼻。',L+[['希腊 oûs／ōt-〔耳〕与 lárynx／laryng-〔喉〕→ oto- + laryngo- + -logy','用耳与喉的构词成分命名专业'],['英语 otolaryngology','耳鼻喉相关的医学专科，常简称 ENT']],'这几个部位在功能和解剖上相互联系。英文医院常用 ENT 帮人快速辨认，不要求患者每次都读出这个长词；更长形式 otorhinolaryngology 明列鼻的成分。','an otolaryngology clinic；paediatric otolaryngology；training in otolaryngology。','audiology 重点在听觉和平衡相关评估、康复；otolaryngology 是范围更广的耳鼻喉医学专科。',('The otolaryngology clinic assessed problems affecting the patient’s voice.','耳鼻喉科门诊评估了影响患者嗓音的问题。'),('The sign used “ENT” alongside “otolaryngology” to help visitors find the clinic.','标牌在 otolaryngology 旁边也写了 ENT，方便来访者找到门诊。'),sources=['https://en.wiktionary.org/wiki/otolaryngology#English','https://www.entnet.org/']),
E('hepatology','英 /ˌhepəˈtɒlədʒi/；美 /ˌhepəˈtɑːlədʒi/','肝病学；肝脏病专科','围绕肝脏怎样工作、怎样受损和怎样发生疾病展开研究与诊疗。','hepato- 来自希腊 hêpar、词干 hēpat- “肝”，加 -logy；hep- 不表示帮助的 help。',L+[['希腊 hêpar／hēpat-〔肝〕→ hepato- + -logy','以肝脏为中心的医学构词'],['英语 hepatology','研究肝脏结构、功能及疾病的医学领域']],'肝参与代谢和许多身体过程，因此肝病学会结合化验、影像及病史等信息。这个词标出专科方向，不是某一种肝病的名字。','a hepatology clinic；clinical hepatology；a hepatology specialist。','hepatitis 是肝炎这一类疾病名称；hepatology 是研究和诊治肝脏问题的领域。',('The hepatology team discussed the patient’s liver test results.','肝病科团队讨论了患者的肝功能检查结果。'),('Her research in hepatology focuses on how liver tissue changes over time.','她的肝病学研究关注肝组织随时间怎样变化。'),sources=['https://en.wiktionary.org/wiki/hepatology#English','https://www.merriam-webster.com/dictionary/hepatology']),
E('doxology','英 /dɒkˈsɒlədʒi/；美 /dɑːkˈsɑːlədʒi/','颂荣；赞美神的短颂','在祈祷或礼拜中，用一小段话或歌把赞美献给神。','希腊 dóxa“荣耀、声望” + 说话成分形成 doxología，经中世纪拉丁 doxologia 借入；-logy 这里是话语，不是学科。',L+[['希腊 dóxa + -logía → doxología → 中世纪拉丁 doxologia','表达荣耀与赞美的话语'],['英语 doxology','礼拜中的颂荣、短赞歌']],'常见于基督教礼仪，既可诵念也可歌唱。某些教会谈 the Doxology 时会指一首特别熟悉的颂歌，但一般词义不限于唯一一首。','sing a doxology；a closing doxology；a short doxology。','eulogy 现代常赞颂或追念一个人；doxology 特指宗教中向神表达荣耀与赞美。',('The congregation sang a doxology at the end of the service.','会众在礼拜结束时唱了一首颂荣歌。'),('The manuscript includes a brief doxology after the prayer.','手稿在祈祷文后附有一段简短颂荣。'),sources=['https://en.wiktionary.org/wiki/doxology#English']),
E('logopaedics','英 /ˌlɒɡəˈpiːdɪks/；美式拼写 logopedics，读 /ˌlɑːɡəˈpiːdɪks/，亦 /ˌlɔːɡə-/','言语治疗学；言语治疗','围绕说话、语言表达等方面的困难，进行专业评估与帮助。','logo- 取“话语”，-paed- 联系希腊 paideía“教育、训练”，再加 -ics；不是拉丁 ped- “脚”。',L+[['希腊 lógos〔话语〕与 paideía〔教育、训练〕','近代术语使用的两组古典构词材料'],['英语 logopaedics／logopedics','言语治疗的另一名称；-ics 作学科名时按单数使用']],'在英语中 speech therapy 或 speech and language therapy 更直观常见。相关服务不只针对孩子；词里的教育、训练成分不能把服务对象限成儿童，也不是教人讲得更有逻辑。','a department of logopaedics；training in logopaedics；logopaedics and speech therapy。','logotherapy 是意义疗法；logopaedics 是言语治疗，logo- 在两词里的具体意义不同。',('The university lists logopaedics among its programmes in communication disorders.','这所大学把言语治疗学列为沟通障碍相关课程之一。'),('The department of logopaedics works with children and adults.','言语治疗科为儿童和成年人提供服务。'),sources=['https://www.collinsdictionary.com/dictionary/english/logopaedics','https://www.merriam-webster.com/medical/logopedics','https://www.duden.de/rechtschreibung/Logopaedie','https://www.asha.org/students/about-speech-language-pathology-careers/'])
])
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0685');owned=set(m['owned_words']);prior={'genealogy','phonology','meteorology','meteorologist','meteorological'}
ROOT=[dict(id='C0685',meaning='话语；讲述；推理；研究',core='把看到的东西选出来、讲清楚，再把理由组织起来',image='话语变成 dialogue 的对话、apology 的申辩与道歉；理由变成 logic 的推理；围绕一个对象系统论述，形成 biology、geology 等研究名称。',intro='希腊 légō 有选取、收集和讲述的历史联系；lógos 则涵盖话语、说明、理由、比例等意思。可以先想象“把材料理出来，再把它讲清楚”。但不同词选用了不同含义：logarithm 取比例，logotherapy 取意义，不能每次都只译成“说”。',forms='log-、logo-、-logue、-logy、-logical、-logist 是常见表现。-logy 常用于学科名，也能表示一套故事或一段话语，并不自带科学可靠性的保证。许多学科名是近代用希腊材料创造的词，不是古希腊已有完整学科。-ology 中的 o 往往是连接元音。',branches=[['话语、回应与作品','dialogue、dialog、monologue、prologue、epilogue、apology、apologize、apologetic、apologist、doxology、eulogy、trilogy、tetralogy'],['整理、推理与意义','logic、logical、illogical、logician、analogy、analogous、catalogue、catalog、anthology、logarithm、logarithmic、tautology、logogram、logophile、logotherapy'],['语言、思想与文化研究','etymology、philology、terminology、phonology、ideology、mythology、theology、sociology、ethnology、criminology、phenomenology、musicology'],['生命、形态与环境','biology、microbiology、neurobiology、astrobiology、ecology、morphology、zoology、entomology、ornithology、ethology、embryology、gerontology'],['地球、物质与测量','geology、petrology、seismology、meteorology、metrology、rheology、cryptology、technology'],['心理、身体与医学','psychology、physiology、pathology、epidemiology、neurology、radiology、pharmacology、toxicology、cardiology、dermatology、ophthalmology、urology、nephrology、hepatology、hematology、histology、cytology、virology、bacteriology、otolaryngology、audiology、logopaedics'],['名称不能代替证据','astrology、numerology、phrenology、parapsychology：分别辨认占星、数字神秘论、已被否定的颅相学与超心理主张'],['同形汇合与争议旁支','logistics 的后勤义通常联系法语 logis“住处、军营”，并受计算词 logistique 影响；logistic 的数学用法另接希腊 logistikós，不强行合成一条确定词源']],contrasts='dialogue 的 dia- 不是“二”，多方也能对话。etymology 查词的历史，entomology 研究昆虫。metrology 研究测量，meteorology 研究大气天气。logopaedics 是言语治疗，logotherapy 是意义疗法。logistics 的后勤来源与希腊计算支线有交汇和争议，不能因为字母相似就宣称它必然同源。',practice='看到 -logy，先问前半部分研究什么，再问整词究竟是学科、故事集合、话语，还是历史学说。用“身体怎样运行”解释 physiology，用“疾病怎样发生”解释 pathology，用“在人群中怎样分布”解释 epidemiology；最后比较 etymology 与 entomology 的对象。',words=list(family),sources=['https://www.etymonline.com/word/-logy','https://www.etymonline.com/word/logic','https://www.etymonline.com/word/logistics','https://en.wiktionary.org/wiki/%CE%BB%CF%8C%CE%B3%CE%BF%CF%82#Ancient_Greek'])]
assert {w['word'] for w in W}==(set(family)&owned)-prior,((set(family)&owned)-prior-{w['word'] for w in W})
assert len({w['word'] for w in W})==len(W)
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa'],w['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history']),w['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_29_log.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0685',len(W),'new',len(ROOT[0]['words']),'references',sum(len(w['examples']) for w in W),'examples')
